-- Lliçons fixes de Morfosintaxi del C2 (botó «Aprendre lliçó»).
-- Com les del C1, cada lliçó és una adaptació didàctica de nivell C2 redactada a partir de:
--   - l'abast de cada contingut del C2 (Quadern C2 de la JQCV, 3.2.2), descrit en
--     20261027110000_practice_morfosintaxi_c2.sql;
--   - les regles de la Gramàtica valenciana bàsica (GVB) i de la Gramàtica normativa
--     valenciana (GNV) de l'AVL, descarregades una sola vegada en assets-src/avl/.
-- El contingut es guarda en metadata.lesson, amb els enllaços als apartats de la GVB i la GNV en
-- metadata.lesson.sources. La migració de continguts (20261027110000) conserva metadata.lesson si es
-- torna a aplicar. Tornar a aplicar este fitxer no canvia res més.

UPDATE public.resources r SET
  metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object('lesson', l.lesson)
FROM jsonb_to_recordset($data$[
  {"type": "c2_mor_genere_nombre", "lesson": {"intro": "Aprendràs el gènere dels noms que contrasten amb el castellà, les parelles amb doble forma i amb doble gènere, el plural dels cognoms i dels compostos, i les expressions en què el nombre no coincidix amb el del castellà.", "blocks": [{"title": "Gènere contrastiu amb el castellà", "text": "Al C2 has de dominar el gènere dels noms que el castellà usa amb l'altre gènere i fer concordar **tots** els modificadors. Són **femenins** *una anàlisi*, *la calor*, *la remor*, *la suor*, *una olor*, *la dent*, *la síndrome*, *una icona*, *una marató* i *les alicates*. Són **masculins** *el corrent*, *el dubte*, *el deute*, *el senyal*, *el compte*, *el costum*, *el llegum*, *el marge*, *un avantatge*, *un estratagema* i *un interrogant*. *Esplendor* és preferentment **femení**.", "examples": ["Han fet **una anàlisi exhaustiva** de les dades.", "Feia **una calor apegalosa** i humida.", "La processó va lluir amb **molta esplendor**.", "Hi ha **un corrent d'opinió** contrari al projecte.", "Sobre la data, tenim **un dubte raonable**."], "watch": [{"wrong": "un anàlisi exhaustiu", "right": "una anàlisi exhaustiva"}, {"wrong": "la senyal acústica", "right": "el senyal acústic"}, {"wrong": "aquella costum tan antiga", "right": "aquell costum tan antic"}]}, {"title": "Doble forma de gènere", "text": "Alguns noms tenen una forma masculina i una de femenina per a la **mateixa realitat**: *el gep* i *la gepa*, *el llimer* i *la llimera*, *el teulat* i *la teulada*. En altres parelles, en canvi, el femení designa un objecte **més gran** o d'un **ús diferent**: no són intercanviables (*plat* / *plata*, *ganivet* / *ganiveta*, *perol* / *perola*).", "table": {"head": ["masculí", "femení"], "rows": [["*el gep*, *el llimer*, *el teulat*", "*la gepa*, *la llimera*, *la teulada* (mateix significat)"], ["*el ganivet*: instrument per a tallar", "*la ganiveta*: ganivet gran, de fulla ampla, de carnissers i pescaters"], ["*el perol*: recipient per a guisar o calfar líquids", "*la perola*: perol gran, caldera; recipient fondo per a fregir bunyols"], ["*el plat*: recipient individual per a menjar", "*la plata*: plat gran en què se servixen a taula aliments per a diverses persones"]]}, "examples": ["Talla la carn amb **la ganiveta**, que el ganivet no talla.", "Fregix els bunyols en **la perola**.", "Porta **la plata** de l'arròs al mig de la taula."]}, {"title": "Doble gènere, significat diferent", "text": "Amb **la mateixa forma**, alguns noms canvien de significat segons el gènere. A més dels que ja coneixes (*el fi* / *la fi*, *el còlera* / *la còlera*), al C2 has de dominar parelles com estes:", "table": {"head": ["masculí", "femení"], "rows": [["*el cremallera*: ferrocarril de muntanya amb carril dentat", "*la cremallera*: tancament de dents de la roba"], ["*el paleta* / *la paleta*: obrer de vila", "*la paleta*: palustre; làmina on el pintor disposa els colors"], ["*el post*: lloc ocupat per les tropes", "*la post*: taula de fusta, tauló"], ["*el pudor*: vergonya, recat", "*la pudor*: mala olor"], ["*el salut*: salutació", "*la salut*: bon estat de l'organisme"], ["*el planeta*: astre", "*la planeta*: destí"]]}, "examples": ["**El paleta** va arrebossar la paret amb **la paleta**.", "Han clavat **una post** al portal de l'alqueria."]}, {"title": "El plural dels antropònims", "text": "Amb els **cognoms de dinasties** l'ús vacil·la: *els Àustries* o *els Àustria*, *els Borbons* o *els Borbó*. Altres cognoms dinàstics es preferixen **invariables**: *els Borja* (millor que *els Borges*). Quan el cognom designa **els membres d'una família**, es manté **invariable**: *els March*, *els Trénor*. En canvi, els **malnoms** i els noms propis convertits en comuns prenen la marca de plural.", "table": {"head": ["cas", "plural"], "rows": [["dinasties (vacil·lació)", "*els Àustries* / *els Àustria*; *els Borbons* / *els Borbó*"], ["dinasties (invariable preferent)", "*els Borja*, *els Tudor*, *els Romanov*"], ["famílies", "*els March*, *els Trénor*, *els Cerdà*, *els Querol*"], ["malnoms", "*els Morruts*, *les Paues*"], ["noms propis recategoritzats", "*uns adams*, *uns cicerons*"]]}, "watch": [{"wrong": "els Marchs de Gandia", "right": "els March de Gandia"}, {"wrong": "el palau dels Trénors", "right": "el palau dels Trénor"}]}, {"title": "Plural dels compostos i de les locucions nominals", "text": "Si el compost està **soldat** o porta **guionet**, el plural va al final: *curtmetratges*, *maldecaps*, *gira-sols*. Si està format per **dos substantius separats**, només es pluralitza el primer: *cafés teatre*, *hores punta*, *camions cisterna*. Si és **substantiu + adjectiu**, concorden tots dos: *guàrdies civils*, *baixos relleus*. Compte amb les parelles de significat diferent: *maldecap* (preocupació) i *mal de cap* (dolor).", "examples": ["El festival premia **curtmetratges** valencians.", "Han obert dos **cafés teatre** al barri del Carme.", "La reforma només li ha portat **maldecaps**.", "Amb tant de soroll tinc **mals de cap** constants."], "watch": [{"wrong": "dos cafés teatres", "right": "dos cafés teatre"}, {"wrong": "les hores puntes", "right": "les hores punta"}, {"wrong": "els curtsmetratges", "right": "els curtmetratges"}]}, {"title": "Nombre contrastiu amb el castellà", "text": "Algunes expressions fixen un **nombre diferent** del castellà: *les postres* (cast. *el postre*), *les estovalles* (cast. *el mantel*), *bon dia*, *bona nit* (cast. *buenos días*, *buenas noches*). En altres, el valencià presenta formes pròpies: *anar camps a través* (el DNV recull *camp a través*; cast. *campo a través*) o *llevar l'àncora* (també *llevar àncores*). A més, el nombre pot **canviar el significat** d'un nom: *l'antiguitat* (època) / *les antiguitats* (objectes), *la cort* / *les Corts*, *un record* (memòria) / *records* (salutacions).", "examples": ["Van tornar al mas **camps a través**.", "De **postres** hi havia fruita del temps.", "Para taula i posa **les estovalles** de fil.", "**Bon dia** a tothom!", "Dona **records** a la teua germana."], "watch": [{"wrong": "un postre boníssim", "right": "unes postres boníssimes"}, {"wrong": "Posa el mantel a la taula.", "right": "Posa les estovalles (o les tovalles) a la taula."}]}], "remember": ["Femenins: *una anàlisi*, *la calor*, *la remor*, *la síndrome*, *la dent*. Masculins: *el corrent*, *el dubte*, *el deute*, *el senyal*, *el costum*.", "Mateix significat: *gep* / *gepa*, *teulat* / *teulada*. Significat diferent: *ganivet* / *ganiveta*, *perol* / *perola*.", "*El cremallera* / *la cremallera*, *el paleta* / *la paleta*, *el post* / *la post*.", "Famílies invariables: *els March*, *els Trénor*; dinasties amb vacil·lació: *els Àustries* o *els Àustria*; *els Borja*.", "*Curtmetratges*, *maldecaps*; *cafés teatre*, *hores punta*; *guàrdies civils*.", "*Les postres*, *les estovalles*, *bon dia*; *camps a través* (o *camp a través*), *llevar l'àncora*; *un record* / *records*."], "sources": [{"gram": "GNV", "section": "10.3.1", "title": "El gènere com a marca semàntica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=10_3_1"}, {"gram": "GNV", "section": "10.3.2", "title": "Observacions sobre el gènere d'alguns substantius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=10_3_2"}, {"gram": "GNV", "section": "11.6", "title": "La flexió de nombre en els noms propis", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=11_6"}, {"gram": "GNV", "section": "11.7", "title": "La flexió de nombre en les paraules compostes", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=11_7"}, {"gram": "GNV", "section": "11.9", "title": "El nombre com a marca semàntica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=11_9"}, {"gram": "GNV", "section": "38.2", "title": "La composició", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=38_2"}, {"gram": "GVB", "section": "16.4", "title": "El gènere com a marca semàntica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=16_4"}, {"gram": "GVB", "section": "16.5", "title": "Vacil·lacions en el gènere d'alguns substantius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=16_5"}, {"gram": "GVB", "section": "17.5", "title": "La flexió de nombre en els noms propis", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=17_5"}, {"gram": "GVB", "section": "17.6", "title": "La flexió de nombre en les paraules compostes", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=17_6"}, {"gram": "GVB", "section": "17.8", "title": "El nombre com a marca semàntica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=17_8"}]}},
  {"type": "c2_mor_adjectius", "lesson": {"intro": "Aprendràs a fer concordar l'adjectiu que es referix a més d'un substantiu, el valor de la seua posició, els colors precisats per un nom, els comparatius i superlatius cultes i els prefixos que expressen el grau màxim.", "blocks": [{"title": "Un adjectiu per a diversos substantius", "text": "Si l'adjectiu va **posposat** a dos o més noms en singular, va en **plural**: si tots són del mateix gènere, en pren el gènere; si n'hi ha de masculins i de femenins, va en **masculí plural**. Si va **anteposat**, concorda amb el **primer** substantiu. I dos adjectius coordinats poden anar en **singular** si cadascun es referix a una de les entitats d'un nom plural.", "table": {"head": ["construcció", "exemple"], "rows": [["posposat, mateix gènere", "*una camisa i una jaqueta **blaves***"], ["posposat, gènere diferent", "*el suèter i la brusa **blaus***"], ["anteposat", "*la **necessària** prudència i respecte*"], ["adjectius coordinats amb nom plural", "*les varietats **dolça** i **amarga** de la taronja*"]]}, "watch": [{"wrong": "el suèter i la brusa blaves", "right": "el suèter i la brusa blaus"}, {"wrong": "té la cama i el braç trencada", "right": "té la cama i el braç trencats"}]}, {"title": "Posició i canvi de significat", "text": "L'adjectiu qualificatiu sol anar **posposat**. Anteposat, dona a l'expressió un to **emfàtic** o **literari** (*els polsegosos camins*), i alguns tenen una posició fixa davant del nom (*un mer tràmit*, *el presumpte culpable*, *el lliure albir*). Uns quants **canvien de significat** segons la posició:", "table": {"head": ["anteposat", "posposat"], "rows": [["*un pobre home*: que fa llàstima", "*un home pobre*: sense diners"], ["*una gran persona*: de gran dignitat", "*una persona gran*: de mides considerables"], ["*una certa notícia*: una notícia determinada", "*una notícia certa*: verdadera"], ["*un nou cotxe*: un altre cotxe", "*un cotxe nou*: sense estrenar"], ["*un trist funcionari*: humil", "*un funcionari trist*: afligit"]]}}, {"title": "Colors precisats per un substantiu", "text": "Quan un adjectiu de color va modificat per un **substantiu** que en precisa el to (*blau cel*, *blau marí*, *verd botella*), el compost queda **invariable**: no concorda ni en gènere ni en nombre amb el nom. Els noms que fan d'adjectiu de color també solen quedar invariables (*les bruses taronja*), tot i que alguns ja admeten el plural (*els vestits rosa* o *roses*).", "examples": ["Duia unes sabates **verd botella**.", "Han pintat les persianes **blau cel**.", "Unes cortines **blau marí** i unes bruses **taronja**."], "watch": [{"wrong": "unes camises blaves cel", "right": "unes camises blau cel"}, {"wrong": "uns ulls verds botella", "right": "uns ulls verd botella"}]}, {"title": "Comparatius cults", "text": "Alguns adjectius tenen formes **sintètiques** heretades del llatí que ja expressen la comparació: *major*, *menor*, *millor*, *pitjor*, *superior*, *inferior*, *anterior*, *posterior*, *ulterior*, *exterior*, *interior*. Per això **no** admeten *més* ni *menys*, i en els cultes el segon terme de la comparació s'introduïx amb ***a***, no amb *que*.", "table": {"head": ["comparatiu cult", "significat i règim"], "rows": [["*superior* / *inferior*", "més alt / més baix: *superior **a** la mitjana*"], ["*anterior* / *posterior*", "d'abans / de després: *anterior **a** 1900*"], ["*ulterior*", "que ve després o està més enllà: *en una fase ulterior*"], ["*major* / *menor*", "més gran / més xicotet: *major d'edat*"], ["*millor* / *pitjor*", "més bo / més dolent: *molt millor*"]]}, "watch": [{"wrong": "és més superior que l'altre", "right": "és superior a l'altre"}, {"wrong": "una nota inferior que la teua", "right": "una nota inferior a la teua"}]}, {"title": "Superlatius cultes", "text": "A més de *-íssim* (*boníssim*), hi ha superlatius **cultes**. Alguns fan *-íssim* sobre la base **llatina** (*antic* → ***antiquíssim***). Uns altres prenen el sufix ***-èrrim***, propi de registres molt formals. I els superlatius orgànics *màxim*, *mínim*, *òptim*, *pèssim*, *suprem* i *ínfim* ja indiquen el grau màxim: **no** admeten *molt* ni *més*.", "table": {"head": ["base", "superlatiu culte"], "rows": [["*antic*", "*antiquíssim*"], ["*fidel*", "*fidelíssim*"], ["*lliure*", "*libèrrim*"], ["*cèlebre*", "*celebèrrim*"], ["*pobre*", "*paupèrrim* (o *pobríssim*)"], ["(culte)", "*acèrrim*: molt ferm, tenaç (*uns enemics acèrrims*)"], ["(culte)", "*ubèrrim*: molt fèrtil (*una horta ubèrrima*)"]]}, "watch": [{"wrong": "un resultat molt òptim", "right": "un resultat òptim"}, {"wrong": "la més màxima puntuació", "right": "la màxima puntuació"}]}, {"title": "Prefixos de grau: arxi-, re- i altres", "text": "El grau màxim també s'expressa amb **prefixos**. ***Arxi-*** intensifica adjectius i participis en un registre expressiu (*arxiconegut*); ***re-*** intensifica alguns adjectius i adverbis (*rebò*, *rebé*). En registres cultes i tècnics s'usen *super-*, *hiper-*, *extra-* i *ultra-*: *superabundant*, *hipersensible*, *extrafí*, *ultramodern*. Com que ja expressen el grau màxim, **no** s'han de reforçar amb *molt*.", "examples": ["És una història **arxiconeguda** a tot el poble.", "—Com ha anat l'examen? —**Rebé**!", "Té una pell **hipersensible** al sol.", "Un edifici **ultramodern** al costat de la muralla."], "watch": [{"wrong": "molt arxiconegut", "right": "arxiconegut"}]}], "remember": ["Posposat a noms de gènere diferent, l'adjectiu va en masculí plural: *el suèter i la brusa blaus*.", "Anteposat, concorda amb el primer nom: *la necessària prudència i respecte*.", "*Un pobre home* / *un home pobre*; *una certa notícia* / *una notícia certa*.", "*Blau cel*, *blau marí*, *verd botella*: invariables.", "*Superior a*, *inferior a*, *anterior a*; mai *més superior* ni *més millor*.", "*Antiquíssim*, *libèrrim*, *celebèrrim*, *acèrrim*, *ubèrrim*; *òptim* i *màxim* sense *molt*."], "sources": [{"gram": "GNV", "section": "12.3", "title": "La concordança de l'adjectiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=12_3"}, {"gram": "GNV", "section": "12.2.1", "title": "Els adjectius qualificatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=12_2_1"}, {"gram": "GNV", "section": "38.3", "title": "La composició sintagmàtica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=38_3"}, {"gram": "GVB", "section": "18.3", "title": "La concordança de l'adjectiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=18_3"}, {"gram": "GVB", "section": "18.4", "title": "La posició de l'adjectiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=18_4"}, {"gram": "GNV", "section": "37.7", "title": "La prefixació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=37_7"}, {"gram": "GNV", "section": "37.6", "title": "La sufixació valorativa", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=37_6"}]}},
  {"type": "c2_mor_determinants", "lesson": {"intro": "Aprendràs l'ús de l'article personal i de l'article en topònims, dates i frases fetes, la posició i el valor despectiu del demostratiu, els anafòrics formals i l'expressió de la possessió amb possessius, amb *en* i amb datius.", "blocks": [{"title": "L'article personal", "text": "L'article personal ***en*** (masculí davant de consonant), ***na*** (femení davant de consonant o de *i*, *u* àtones) i ***n'*** (davant de vocal) ja no s'usa en el valencià col·loquial, però es manté **fossilitzat** en molts **topònims** i en les referències a **personatges històrics**. En el valencià actual, els noms de persona van **sense article**.", "table": {"head": ["ús", "exemples"], "rows": [["topònims", "*la Torre d'en Besora*, *la Font d'en Carròs*, *la Font d'en Corts*"], ["carrers i llocs", "*el carrer de Na Jordana*"], ["personatges històrics", "*el rei en Jaume*, *la reina na Jordana*"], ["forma apostrofada", "*n'Albert*, *n'Úrsula*; però *na Isabel*"], ["ús actual general", "*Vicenta arribarà tard.* *Parlaré amb Jordi.*"]]}, "watch": [{"wrong": "la Torre de Besora", "right": "la Torre d'en Besora"}, {"wrong": "la Font de Carròs", "right": "la Font d'en Carròs"}]}, {"title": "Article sí, article no", "text": "La presència de l'article la fixa la **tradició**. Van **sense** article la majoria de poblacions, però el duen *l'Alcora*, *l'Eliana*, *la Nucia*, *el Campello* o *la Vila Joiosa*; el duen les **comarques**, els **rius** i les **muntanyes** (*la Safor*, *el Túria*, *el Montgó*). Amb els **dies** de la setmana s'ometen per a indicar immediatesa (*dijous que ve*) i es posen per a un dia concret o habitual (*el dijous 29*, *els dilluns*). Davant dels **anys** és opcional (*de 2003* o *del 2003*). Molts **proverbis** i **frases fetes** tenen l'article fixat, i no sempre coincidixen amb el castellà.", "examples": ["**Tota pedra** fa paret.", "**Qui** no vullga pols, que no vaja a l'era.", "Va **alçar el cap** i ens va mirar.", "Els xiquets **juguen a pilota** al carrer.", "**Dijous que ve** anirem a l'Eliana."], "watch": [{"wrong": "Ha viscut sempre a Eliana.", "right": "Ha viscut sempre a l'Eliana."}]}, {"title": "El demostratiu: posició i valor despectiu", "text": "El demostratiu va normalment **davant** del nom: *aquella casa*. També pot anar **darrere**, si el nom ja porta l'article definit: *el llibre aquell*. En esta posició sol tindre un **valor despectiu** o de distanciament afectiu. El valencià manté els **tres graus** (*este*, *eixe*, *aquell*) i les formes simples i reforçades (*aquest*, *aqueix*) són igualment vàlides.", "examples": ["**Aquella casa** és immensa.", "**El llibre aquell** és interessant.", "Hi havia **el cotxe aquell** que sempre aparca damunt la vorera.", "No em parles més **de l'home eixe**."]}, {"title": "Altres determinants anafòrics", "text": "En la llengua escrita formal, a més dels demostratius, s'usen **participis i adjectius** amb funció anafòrica, és a dir, per a reprendre un element ja esmentat: *el mencionat*, *el dit*, *l'esmentat*, *l'anomenat*, *el citat*, *el referit*, *el present*. Concorden amb el nom i van precedits de l'article.", "examples": ["**L'esmentada** oposició no sempre té un reflex formal.", "El projecte es presentarà dilluns; **el dit** projecte inclou tres fases.", "**La present** resolució entrarà en vigor l'endemà.", "En **el citat** informe no consta cap data."]}, {"title": "Possessius en expressions fixes", "text": "En moltes locucions el possessiu **posposat** alterna amb *de* + pronom: *darrere seu* o *darrere d'ell*, *prop nostre*, *en contra vostra*. El possessiu va en femení si la locució conté un nom femení (*per culpa seua*, *a costa vostra*). Algunes construccions contrasten amb el castellà, que hi usaria el possessiu anteposat o un pronom:", "table": {"head": ["valencià", "castellà"], "rows": [["*a càrrec seu*", "*a su cargo*"], ["*a gust teu*", "*a tu gusto*"], ["*a favor nostre*", "*a nuestro favor*"], ["*per culpa seua*", "*por su culpa*"]]}, "watch": [{"wrong": "Ho farà a seu càrrec.", "right": "Ho farà a càrrec seu (o al seu càrrec)."}]}, {"title": "La pertinença amb en i amb datius", "text": "Quan el posseïdor és clar pel context, el valencià **evita el possessiu**. Si el posseïdor ja ha aparegut, la pertinença es pot expressar amb el pronom ***en*** (complement del nom). Si és una persona afectada, especialment amb **parts del cos** i objectes personals, s'usa un **pronom datiu** i l'article definit.", "examples": ["Del poble, **en** coneixia l'origen. (= l'origen del poble)", "D'aquella novel·la, **en** recorde el final.", "**Li** feia mal **l'esquena**.", "**Li** han robat **la cartera**.", "Renta't **les** mans."], "watch": [{"wrong": "Coneixia el seu origen (del poble).", "right": "En coneixia l'origen."}, {"wrong": "Em fa mal la meua esquena.", "right": "Em fa mal l'esquena."}]}], "remember": ["Article personal fossilitzat: *la Torre d'en Besora*, *la Font d'en Corts*, *el carrer de Na Jordana*.", "Amb article: *l'Eliana*, *la Nucia*, *la Safor*, *el Túria*; *jugar a pilota*, *alçar el cap*.", "*El cotxe aquell*: demostratiu posposat, sovint despectiu.", "Anafòrics formals: *l'esmentat*, *el dit*, *el mencionat*, *l'anomenat*.", "*A càrrec seu*, *a gust teu*, *per culpa seua*, *en contra vostra*.", "*En coneixia l'origen*; *li feia mal l'esquena*."], "sources": [{"gram": "GNV", "section": "15.2.2", "title": "Observacions sobre l'ús de l'article definit", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=15_2_2"}, {"gram": "GNV", "section": "15.4", "title": "L'article personal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=15_4"}, {"gram": "GVB", "section": "19.2.4", "title": "L'ús de l'article definit davant de topònims", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_2_4"}, {"gram": "GVB", "section": "19.4", "title": "L'article personal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_4"}, {"gram": "GVB", "section": "10.4", "title": "L'apostrofació dels articles personals en i na", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_4"}, {"gram": "GNV", "section": "16.3.1", "title": "Caracterització general", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=16_3_1"}, {"gram": "GNV", "section": "16.3.3", "title": "Usos díctics i anafòrics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=16_3_3"}, {"gram": "GNV", "section": "17.2.2", "title": "Aspectes sintàctics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=17_2_2"}, {"gram": "GVB", "section": "21.2.3", "title": "Alternança dels possessius i els pronoms personals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=21_2_3"}, {"gram": "GVB", "section": "21.2.4", "title": "Ús impropi dels possessius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=21_2_4"}, {"gram": "GNV", "section": "23.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_1"}, {"gram": "GNV", "section": "32.3", "title": "El complement indirecte", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_3"}]}},
  {"type": "c2_mor_pronoms_forts", "lesson": {"intro": "Aprendràs quan s'usa *jo* i quan *mi* darrere de preposició, el reforç dels pronoms amb *mateix*, l'ús del pronom fort referit a coses i les implicacions sintàctiques del tractament amb *vosté* i amb *vós*.", "blocks": [{"title": "Jo i mi darrere de preposició", "text": "Com a norma, ***jo*** fa de **subjecte** i ***mi*** va darrere de **preposició**: *Es va dirigir a mi*, *sense mi*, *contra mi*. Però s'usa *jo* quan la preposició regix **diversos elements coordinats**: *entre tu i jo*, *contra ella i jo*. Algunes preposicions i locucions (*malgrat*, *llevat de*, *segons*, *ultra*) també poden anar amb *jo*, encara que són usos poc habituals i hi ha alternatives més naturals.", "table": {"head": ["context", "pronom"], "rows": [["preposició + un sol pronom", "*per a **mi***, *sense **mi***, *contra **mi***"], ["preposició + elements coordinats", "*entre tu i **jo***, *contra ella i **jo***"], ["però si es repetix la preposició", "*contra ella i contra **mi***"], ["*llevat de*, *segons*, *malgrat* (poc habitual)", "*tots llevat de **jo*** (millor *menys jo*, *excepte jo*)"], ["subjecte d'un infinitiu", "*Ho van fer sense **jo** dir-li res.*"]]}, "watch": [{"wrong": "Entre tu i mi ho acabarem.", "right": "Entre tu i jo ho acabarem."}, {"wrong": "Ho han fet per a jo.", "right": "Ho han fet per a mi."}]}, {"title": "El reforç amb mateix", "text": "L'indefinit ***mateix*** reforça els pronoms forts, sobretot amb valor **reflexiu**, i hi **concorda** en gènere i nombre: *de mi mateixa*, *en vosaltres mateixos*. En tercera persona, el reflexiu específic és ***si***, que també es reforça: *parlava de si mateix*. Hi ha expressions fixades sense reforç: *fora de si*, *tornar en si*, *entre si*. Amb els pronoms personals es comporta com a adjectiu i **concorda** (*elles mateixes*); només quan funciona com a adverbi ('precisament') pot quedar invariable: *ara mateix*, *allí mateix*, *la presidenta mateix*.", "examples": ["Hi van anar tots, **llevat de jo mateixa**.", "Carme sempre parla de **si mateixa**.", "Només penseu en **vosaltres mateixos**.", "La notícia el va posar **fora de si**."], "watch": [{"wrong": "Parla molt d'ella mateix (reflexiu).", "right": "Parla molt d'ella mateixa (o de si mateixa)."}]}, {"title": "El pronom fort referit a coses", "text": "Per a referir-se a coses, el pronom fort de tercera persona **no** fa de complement directe ni indirecte, i amb preposició es preferixen ***en***, ***hi***, un demostratiu, un relatiu o l'el·lipsi. En canvi, sí que és normal quan fa de **reflexiu** o va modificat per *mateix*, *sol* o *a soles* (*per ell mateix*, *ella sola*). En registres formals també s'usa amb quantificadors: *tres d'ells*, *la majoria d'elles*.", "examples": ["Ja he vist la foto; no vull que **me'n** parles. (no *que em parles d'ella*)", "Han promés inversions i tots **hi** confien. (no *confien en elles*)", "El motor pot funcionar **per ell mateix**.", "Es van presentar quatre projectes, **tres d'ells** d'estudiants."], "watch": [{"wrong": "La directora va presentar un document; en ell s'arrepleguen les propostes.", "right": "La directora va presentar un document, en el qual s'arrepleguen les propostes."}]}, {"title": "Vosté: concordança de tercera persona", "text": "***Vosté*** i ***vostés*** designen l'interlocutor, però sintàcticament es comporten com a pronoms de **tercera persona**: el verb, els **possessius** (*seu*, *seua*) i els **pronoms febles** (*el*, *la*, *li*, *els*, *se*) van en tercera persona. Els adjectius concorden amb el **sexe** de la persona. Barrejar formes de segona i de tercera en un mateix text és un error de coherència.", "table": {"head": ["element", "amb tu", "amb vosté"], "rows": [["verb", "*Què desitges?*", "*Què desitja?*"], ["possessiu", "*la teua sol·licitud*", "*la seua sol·licitud*"], ["pronom feble", "*T'ho enviarem.*", "*Li ho enviarem.*"], ["reflexiu", "*Assenta't.*", "*Assente's.*"], ["concordança", "*Estàs cansada?*", "*Està cansada, senyora?*"]]}, "watch": [{"wrong": "Vosté, què et pareix?", "right": "A vosté, què li pareix?"}, {"wrong": "Senyor, ompliu la vostra sol·licitud (amb vosté).", "right": "Senyor, ompliga la seua sol·licitud."}]}, {"title": "Vós i la segona persona del plural", "text": "***Vós*** és un pronom de **segona persona del singular** que concorda amb el verb en **plural**: *Vós direu*. Es conserva com a tractament pròxim i respectuós (*Com et trobes? —Bé, i vós?*) o molt solemne (*A vós, Senyor*). Els febles i els possessius que s'hi corresponen són els de segona del plural: ***vos*** i ***vostre***. En el llenguatge administratiu és molt habitual el tractament amb la segona del plural sense pronom explícit.", "examples": ["**Vós** direu, padrina: què vos pose?", "Distingit senyor: **vos** trametem la informació que **heu** sol·licitat.", "Ompliu les caselles amb **les vostres** dades personals.", "Senyor: **vós** sabeu que **vos** estimem."]}], "remember": ["*Sense mi*, *per a mi*; però *entre tu i jo*, *contra ella i jo*.", "*Llevat de jo*, *segons jo*: possibles però poc habituals; millor *menys jo*, *al meu parer*.", "*De si mateix*, *de mi mateixa*: el reforç reflexiu concorda.", "Coses: *me'n parles*, *hi confien*, *en el qual*; no *d'ella*, *en elles*, *en ell*.", "*Vosté*: verb, possessiu i febles en tercera persona (*Li ho enviarem*, *la seua sol·licitud*).", "*Vós*: segona persona del singular amb el verb en plural (*Vós direu*); febles *vos*, possessiu *vostre*."], "sources": [{"gram": "GNV", "section": "21.3.1", "title": "L'oposició entre jo i mi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=21_3_1"}, {"gram": "GNV", "section": "21.3.2", "title": "Les formes de cortesia", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=21_3_2"}, {"gram": "GNV", "section": "21.3.3", "title": "Els pronoms reflexius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=21_3_3"}, {"gram": "GNV", "section": "21.3.4", "title": "Els pronoms de tercera persona referits a coses", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=21_3_4"}, {"gram": "GVB", "section": "25.3.1", "title": "L'oposició entre jo i mi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=25_3_1"}, {"gram": "GVB", "section": "25.3.2", "title": "Les formes de cortesia", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=25_3_2"}, {"gram": "GVB", "section": "24.2.12", "title": "Mateix", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_2_12"}]}},
  {"type": "c2_mor_pronoms_febles", "lesson": {"intro": "Aprendràs a pronominalitzar l'atribut definit, el predicatiu, el complement circumstancial de manera i el complement del nom, a reconéixer les formes plenes fixades en modismes i a triar entre pronom acusatiu i datiu segons el règim del verb.", "blocks": [{"title": "L'atribut: ho i el pronom definit", "text": "L'atribut de *ser*, *estar*, *paréixer* i *semblar* es pronominalitza amb ***ho***, tant si és un adjectiu com un sintagma nominal o preposicional. El pronom *ho* també reprén **sintagmes nominals definits**: *—És el nou metge? —Sí que **ho** és*. En registres **molt formals** s'ha recomanat a vegades, en este cas, el pronom **definit** (*Sí que **l'**és*), i el Quadern C2 hi inclou les formes *el*, *la*, *els*, *les*. És un ús cult i minoritari: *ho* és sempre correcte.", "examples": ["És estranger, però no **ho** sembla.", "Aquella camisa és de cotó o no **ho** és?", "—És el nou metge? —Sí, sí que **ho** és. (molt formal: Sí que **l'**és.)"], "watch": [{"wrong": "És estranger, però no el sembla.", "right": "És estranger, però no ho sembla."}, {"wrong": "—Està malalt? —Sí que l'està.", "right": "—Està malalt? —Sí que ho està."}]}, {"title": "En i hi amb predicatius", "text": "El **predicatiu** del verb *fer (de)* es pronominalitza amb ***en***, i també l'atribut de ***fer-se*** quan significa 'passar a formar part' (*fer-se soci*). La majoria d'altres predicatius i l'atribut dels verbs **quasicopulatius** (*tornar-se*, *fer-se* 'esdevenir', *posar-se*) es pronominalitzen amb ***hi***.", "table": {"head": ["construcció", "pronominalització"], "rows": [["*fer de dependenta*", "*De dependenta, ja fa temps que no **en** fa.*"], ["*fer-se soci del club*", "*Encara no s'ha fet soci, però prompte **se'n** farà.*"], ["*fer-se com una bacona*", "*Sí que **s'hi** ha fet.*"], ["*tornar-se curt*", "*Deien que es faria més curt, però no **s'hi** ha tornat.*"], ["*parlar com un boig*", "*Li vaig dir que no **m'hi** parlara mai més.*"]]}, "watch": [{"wrong": "Encara no és soci, però prompte s'ho farà.", "right": "Encara no és soci, però prompte se'n farà."}]}, {"title": "Hi en circumstancials de manera i instrument", "text": "A més dels locatius, ***hi*** pot pronominalitzar **altres complements circumstancials**: de **manera**, **instrumentals** i **comitatius**. És un ús que s'ha perdut en part en la llengua espontània, però convé mantindre'l en els registres formals, d'acord amb la tradició clàssica i literària.", "examples": ["Sempre **hi** parla, tranquil·lament. (hi = tranquil·lament)", "Em va confessar que amb ell ja no **hi** podia viure. (hi = amb ell)", "M'he quedat sense tinta i no **hi** puc escriure. (hi = amb l'estilogràfica)", "Has pensat en la proposta? —Sí que **hi** he pensat."]}, {"title": "En com a complement del nom", "text": "***En*** pronominalitza el complement introduït per ***de*** que depén d'un **nom** amb funció de complement directe o de subjecte posposat, quan fa referència a la part d'un conjunt o a allò de què es parla. També reprén el complement d'un **adjectiu** atribut (*n'està satisfet*) i el complement de règim amb *de*.", "examples": ["Vam entrar al museu, però només **en** vam visitar una part. (en = del museu)", "D'aquella novel·la, **en** recorde sobretot el final.", "Si hi ha cireres, porta-me**'n** una cistella.", "S'ha comprat un ordinador i **n'**està molt content."], "watch": [{"wrong": "Vam visitar el museu, però només vam veure una part d'ell.", "right": "Vam visitar el museu, però només en vam veure una part."}]}, {"title": "Formes plenes en modismes", "text": "Davant de verb començat per consonant, la forma normal és la **reforçada** (*em*, *et*, *es*, *en*). Però es mantenen les **formes plenes** en modismes estereotipats com ***tant me fa*** i ***tant se val***, i se sol usar *se* davant de verb començat per *s* per a evitar l'assimilació (*No se sap res*). En la resta de casos, en els registres formals són preferibles les reforçades.", "examples": ["Vinga hui o demà, **tant me fa**.", "**Tant se val** qui guanye: farem festa igualment.", "L'acte **se** celebrarà dissabte a la plaça.", "No **se** sap res encara."]}, {"title": "Acusatiu o datiu segons el verb", "text": "El pronom depén del **règim** del verb en valencià, no del castellà. Són **transitius**, i porten *el*, *la*, *els*, *les*, *avisar*, *ajudar*, *obeir*, *felicitar*: *avisar-**lo***, *ajudar-**la***, *obeir-**los***. *Telefonar* és **intransitiu** i la persona fa de complement indirecte: *telefonar-**li***. Recorda, a més, que el participi concorda amb els acusatius de tercera persona.", "table": {"head": ["verb", "pronom", "exemple"], "rows": [["*avisar* (tr.)", "*el*, *la*", "*Avisa'**l** abans de vindre.*"], ["*ajudar* (tr.)", "*el*, *la*", "*Necessita que **l'**ajuden a vestir-se.*"], ["*obeir* (tr.)", "*els*, *les*", "*Els mestres? Els xiquets **els** han d'obeir.*"], ["*felicitar* (tr.)", "*el*, *la*", "*Ja **l'**he felicitada.*"], ["*telefonar* (intr.)", "*li*, *els*", "***Li** he telefonat per a dir-li la notícia.*"]]}, "watch": [{"wrong": "Li vaig avisar del canvi d'hora.", "right": "El vaig avisar del canvi d'hora."}, {"wrong": "La vaig telefonar ahir.", "right": "Li vaig telefonar ahir."}]}], "remember": ["Atribut: *Sí que ho és*; molt formal i minoritari: *Sí que l'és*.", "*Fer de*: *no en fa*; *fer-se soci*: *se'n farà*; quasicopulatius: *s'hi ha tornat*.", "*Hi* reprén circumstancials de manera i instrument: *Sempre hi parla, tranquil·lament*.", "*En* complement del nom: *en vam visitar una part*, *en recorde el final*.", "Formes plenes fixades: *tant me fa*, *tant se val*, *no se sap*.", "*Avisar-lo*, *ajudar-lo*, *obeir-lo*, *felicitar-lo*; però *telefonar-li*."], "sources": [{"gram": "GNV", "section": "23.3", "title": "El pronom neutre", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_3"}, {"gram": "GNV", "section": "23.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_1"}, {"gram": "GNV", "section": "23.4.2", "title": "El pronom hi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_2"}, {"gram": "GNV", "section": "22.3.2", "title": "Formes plenes, reforçades, reduïdes i elidides", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=22_3_2"}, {"gram": "GNV", "section": "23.2.2", "title": "Els pronoms no reflexius de tercera persona", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_2_2"}, {"gram": "GNV", "section": "32.2", "title": "El complement directe i la transitivitat", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_2"}, {"gram": "GNV", "section": "32.3", "title": "El complement indirecte", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_3"}, {"gram": "GVB", "section": "27.3", "title": "El pronom neutre", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_3"}, {"gram": "GVB", "section": "27.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_4_1"}, {"gram": "GVB", "section": "27.4.2", "title": "El pronom hi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_4_2"}]}},
  {"type": "c2_mor_combinacions", "lesson": {"intro": "Aprendràs les restriccions que impedixen combinar certs pronoms febles, l'orde i la forma de les combinacions binàries més difícils (*li'n*, *l'hi*, *els en*, *n'hi*), les combinacions ternàries del tipus *se me n'ha anat* o *menjar-se-me-la* i la manera correcta d'escriure-les.", "blocks": [{"title": "Restriccions: un sol pronom per a cada casella", "text": "L'orde dels pronoms febles és fix, i només es poden combinar pronoms que ocupen **posicions diferents** en la sèrie; mai dos de la mateixa (dos *en*, dos *hi*, dos datius...). Per això, quan un sintagma conté dos elements que es pronominalitzarien amb ***en***, només se'n pot substituir **un**. De *Cuinaran uns quants pastissos de moniato*, *en* pot reprendre el **nucli** (i el complement queda amb la preposició partitiva *de*) o bé el **complement del nom**, però no les dos coses alhora.", "table": {"head": ["oració", "pronominalització"], "rows": [["*Cuinaran uns quants pastissos de moniato.*", "*En cuinaran uns quants **de moniato**.* (en = pastissos)"], ["", "*En cuinaran uns quants **pastissos**.* (en = de moniato)"], ["*Has menjat pomes?*", "*Me n'he menjat tres **de roges**.* (n' = pomes)"], ["*Si no tens aigua de la font...*", "*...posa-me'n **de l'aixeta**.*"]]}, "watch": [{"wrong": "N'en cuinaran uns quants.", "right": "En cuinaran uns quants de moniato. / En cuinaran uns quants pastissos."}]}, {"title": "Orde i forma de les combinacions", "text": "L'orde és sempre: ***se*** → 2a persona (*te*, *vos*) → 1a persona (*me*, *nos*) → datiu de 3a (*li*, *los*) → acusatiu de 3a (*lo*, *la*, *los*, *les*) → ***ne*** → ***hi*** / ***ho***. En posició proclítica, el primer pronom adopta la **forma plena** (*me la*, *te'n*, *se'm*), però s'elidix davant de *ho* i *hi* (*m'ho*, *s'hi*). Si el primer pronom acaba en *-s*, el segon pren la forma **reforçada**: *ens els*, *els en*, *vos ho*. Canviar l'orde de *se* (*me s'ha*, *li s'ha*) no és acceptable en registres formals.", "examples": ["**Me la** van regalar per Nadal.", "Quan **te n'**aniràs a Xàtiva?", "No **se'm** va acudir preguntar per tu.", "**Ens els** portaran demà. / Emportem-**nos-els** ja!"], "watch": [{"wrong": "Me s'ha fet tard.", "right": "Se m'ha fet tard."}, {"wrong": "Li s'ha perdut la clau.", "right": "Se li ha perdut la clau."}]}, {"title": "Combinacions binàries difícils", "text": "Algunes combinacions es confonen sovint. El valencià combina el datiu *li* amb l'acusatiu: *li'l*, *li la*, *li'ls*, *li les*, *li ho*. La forma ***l'hi*** és la combinació de *lo* + *hi* locatiu, encara que en els parlars més septentrionals també equival a *li* + *lo* (*L'hi he donat* = *Li l'he donat*). Recorda també que *los* + *ne* fa ***els en*** i que *ne* + *hi* fa ***n'hi***.", "table": {"head": ["combinació", "exemple"], "rows": [["*li* + *ne* → *li'n*", "*Li agraden les novel·les: **li'n** vaig regalar un parell.*"], ["*li* + *ho* → *li ho*", "*Ja **li ho** he explicat tot.*"], ["*lo* + *hi* → *l'hi*", "*El cotxe? **L'hi** he deixat, al garatge.*"], ["*los* + *ne* → *els en*", "*No **els en** vull dir res.* / *No vull dir-**los-en** res.*"], ["*ne* + *hi* → *n'hi*", "*Al calaix? **N'hi** he posat tres.*"], ["*los* + *los* → *els els*", "*Els llibres, als alumnes? Ja **els els** hem tornats.*"]]}, "watch": [{"wrong": "Els llibres, als alumnes? Ja els hi hem tornat.", "right": "Ja els els hem tornats."}, {"wrong": "Se n'anirem demà (registre formal).", "right": "Ens n'anirem demà."}, {"wrong": "Aneu-se'n d'ací!", "right": "Aneu-vos-en d'ací!"}]}, {"title": "Combinacions ternàries", "text": "Molt més esporàdicament es combinen **tres** pronoms. Seguixen el mateix orde fix i solen incloure un pronom de primera o segona persona que indica la persona **afectada** per l'acció (*me*, *te*), que es pot ometre sense que canvie el significat bàsic: *Se n'ha anat* / *Se **me** n'ha anat*. Davant del verb, els pronoms van separats o apostrofats; darrere, units amb guionets.", "table": {"head": ["pronoms", "exemple"], "rows": [["*se* + *me* + *ne*", "*El sant **se me n'**ha anat al cel.*"], ["*se* + *te* + *ne*", "*Quan veus pastissos, **se te'n** van els ulls.*"], ["*se* + *me* + *la*", "*Si deixes la coca ací, el gos va a menjar-**se-me-la**.*"], ["*se* + *me* + *lo*", "*Ha vingut el gat i **se me l'**ha menjat.*"]]}, "watch": [{"wrong": "Me se n'ha anat el sant al cel.", "right": "Se me n'ha anat el sant al cel."}, {"wrong": "menjar-me-se-la", "right": "menjar-se-me-la"}]}, {"title": "Apòstrofs i guionets en les combinacions", "text": "En les combinacions amb formes elidides o reduïdes, l'**apòstrof** es col·loca **tan a la dreta com siga possible**: *se n'ha anat*, però *se'n va anar*; *li l'he portat*, però *li'l portaré*. El pronom *lo* combinat amb *ne* pren la forma ***l'en***, perquè *le* no existix com a pronom. Darrere del verb, els pronoms s'unixen amb **guionets** o apòstrofs: *compra-te-la*, *ves-te'n*, *dir-li-ho*, *dona-li'l*.", "examples": ["Ja **se n'**ha anat. / Ja **se'n** va anar.", "No **li l'**he portat encara; **li'l** portaré demà.", "De les nostres preocupacions, **l'en** vaig fer partícip.", "No vols **dir-m'ho**?"], "watch": [{"wrong": "Se'n ha anat.", "right": "Se n'ha anat."}, {"wrong": "Dona-li-el.", "right": "Dona-li'l."}, {"wrong": "Le'n vaig fer partícip.", "right": "L'en vaig fer partícip."}]}], "remember": ["Orde fix: *se* → *te/vos* → *me/nos* → *li/los* → *lo/la/los/les* → *ne* → *hi/ho*.", "Mai dos pronoms de la mateixa posició: *En cuinaran uns quants de moniato*, no *n'en*.", "*Se m'ha fet tard*, *se li ha perdut* (no *me s'ha*, *li s'ha*).", "*Li'n*, *li ho*, *l'hi* (lo + hi), *els en*, *n'hi*, *els els*.", "Ternàries: *se me n'ha anat*, *se te'n van els ulls*, *menjar-se-me-la*.", "Apòstrof a la dreta: *se n'ha anat*, *li l'he portat*; *l'en vaig fer partícip*."], "sources": [{"gram": "GNV", "section": "22.4.1", "title": "L'orde dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=22_4_1"}, {"gram": "GNV", "section": "22.4.2", "title": "La forma dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=22_4_2"}, {"gram": "GNV", "section": "22.3.2", "title": "Formes plenes, reforçades, reduïdes i elidides", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=22_3_2"}, {"gram": "GNV", "section": "23.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_1"}, {"gram": "GNV", "section": "23.2.2", "title": "Els pronoms no reflexius de tercera persona", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_2_2"}, {"gram": "GVB", "section": "26.4.1", "title": "L'orde dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=26_4_1"}, {"gram": "GVB", "section": "26.4.2", "title": "La forma dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=26_4_2"}, {"gram": "GVB", "section": "27.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_4_1"}, {"gram": "GVB", "section": "27.4.2", "title": "El pronom hi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_4_2"}]}},
  {"type": "c2_mor_relatius", "lesson": {"intro": "Aprendràs a triar el relatiu adequat en registre formal (*que*, *què*, *qui*, *el qual*, *on*), la caiguda de la preposició amb antecedents de temps, les relatives neutres (*la qual cosa*, *cosa que*), les construccions *n'hi ha que* i *hi ha qui*, el relatiu complement d'un infinitiu o un gerundi, i a evitar el pronom feble redundant.", "blocks": [{"title": "Que, què, qui i el qual", "text": "Sense preposició, el relatiu de les **especificatives** és ***que***; en les **explicatives** alternen *que* i *el qual*, però **no** *qui*. Darrere de preposició s'usa ***què*** (coses, i també persones), ***qui*** (només persones) o ***el qual*** (persones i coses). *Què* i *qui* només van amb les àtones *a*, *en*, *de*, *amb* i, menys sovint, *per*; amb preposicions tòniques cal *el qual*. ***El que*** només s'usa **sense antecedent** (*Fes el que vullgues*); amb antecedent explícit no és admissible en registres formals.", "table": {"head": ["context", "relatiu", "exemple"], "rows": [["especificativa, sense preposició", "*que*", "*El client **que** havia tacat.*"], ["explicativa, sense preposició", "*que* / *el qual*", "*Aquell polític, **que** / **el qual** no té escrúpols...*"], ["amb preposició àtona", "*què*, *qui*, *el qual*", "*La persona **en qui** més confie.* *El tema **de què** parles.*"], ["amb preposició tònica", "*el qual*", "*Una malaltia **contra la qual** no podem lluitar.*"], ["valor possessiu", "*del qual*", "*Un jugador l'habilitat **del qual** és dubtosa.*"]]}, "watch": [{"wrong": "Vam arribar a una ciutat en la que no hi havia cotxes.", "right": "...en què (o en la qual, o on) no hi havia cotxes."}, {"wrong": "Aquell polític, qui no té escrúpols, firmarà.", "right": "Aquell polític, que (o el qual) no té escrúpols, firmarà."}, {"wrong": "Va gratificar el client el qual havia tacat.", "right": "Va gratificar el client que havia tacat."}]}, {"title": "La caiguda de la preposició: el dia que vaig nàixer", "text": "El relatiu temporal *quan* s'usa **sense antecedent** (*Vine quan pugues*). Si hi ha un **antecedent temporal** explícit, s'usa ***que*** sense preposició, o bé *en què* / *en el qual*: *el dia que vaig nàixer*. Amb el nom *manera*, el relatiu pot ser *com*, *que*, *en què* o *en la qual*. El locatiu ***on*** es preferix **sense** la preposició *a* en registres formals, i *en què* / *en el qual* són preferibles quan la localització és metafòrica.", "examples": ["Recorde perfectament **el dia que** vaig nàixer el meu fill.", "Això va passar **l'any que** (o **en què**) va faltar el pare.", "**De la manera com** (o **que**) t'ha contestat, ja ho sap.", "Esta és la carpeta **on** guarde els documents importants.", "Hi ha llengües **en què** el subjecte va al final de l'oració."], "watch": [{"wrong": "El dia quan vaig nàixer.", "right": "El dia que vaig nàixer."}]}, {"title": "Relatives neutres i construccions particulars", "text": "Per a reprendre **tota una oració** s'usa ***la qual cosa*** o ***cosa que*** (no *lo que* ni *el que*). En registres formals l'antecedent es pot **repetir** (*virus que...*, *la qual suma...*). El relatiu *el qual* pot ser, a més, el complement d'un **infinitiu** o d'un **gerundi** que encapçala la relativa: *un permís, per a obtindre el qual...*, *la vaga, aprofitant la qual...*; amb *què* o *que* no és possible. Fixa't també en ***n'hi ha que*** ('alguns') i ***hi ha qui*** ('alguna persona'), amb *qui* sense antecedent.", "examples": ["El president no va admetre rèpliques, **la qual cosa** (o **cosa que**) va ser molt criticada.", "El concert va costar trenta mil euros, **quantitat que** assumirà la Diputació.", "Concediran un permís, **per a obtindre el qual** caldrà presentar un informe.", "Van convocar una vaga, **aprofitant la qual** molts van fer pont.", "Entre els integrants del grup **n'hi ha que** tenen idees estrafolàries.", "**Hi ha qui** opina que el president farà canvis."], "watch": [{"wrong": "No va admetre rèpliques, lo que va ser criticat.", "right": "...la qual cosa (o cosa que) va ser criticada."}]}, {"title": "Relatives analítiques i pronom redundant", "text": "En la llengua col·loquial, *que* es reduïx a vegades a un simple nexe i un pronom feble o un possessiu fa la funció del relatiu (construcció **analítica**). També apareix un **pronom redundant** al costat del relatiu (*a qui li*). Són usos **impropis dels registres formals**, on cal la construcció **sintètica**:", "table": {"head": ["no formal", "formal"], "rows": [["*Aquella és la xica a qui **li** he demanat l'adreça.*", "*Aquella és la xica **a qui** he demanat l'adreça.*"], ["*És un home que no **li** lluïx la faena.*", "*És un home **a qui** no lluïx la faena.*"], ["*Tinc un amic que **el seu pare** és obrer.*", "*Tinc un amic **el pare del qual** és obrer.*"], ["*És un tema que no **el** domine.*", "*És un tema **que** no domine.*"], ["*És un poble que hi ha molta gent.*", "*És un poble **on** hi ha molta gent.*"]]}}, {"title": "Interrogatius i exclamatius", "text": "***Què*** interrogatiu porta accent i pregunta per coses (*Què vols?*, *De què et queixes?*); ***quin*** acompanya un nom (*Quin llibre vols?*). Els interrogatius es poden **reforçar** amb un substantiu interjectiu (*dimoni*, *diable*...), sempre en registres expressius: *Què dimonis fas?* No s'ha de confondre *què* amb el quantitatiu exclamatiu ***que***, sense accent, davant d'adjectiu o adverbi (*Que bonic!*). En les interrogatives indirectes es mantenen els mateixos interrogatius (*No sé **què** vol*, *Pregunta-li **per què** ha vingut*).", "examples": ["**Què dimonis** fas, a estes hores?", "**On botons** ha anat a parar el comandament?", "**Que** bonic que és el teu poble! / **Quina** calor que fa!", "No sabia **sobre què** havia de parlar."], "watch": [{"wrong": "Què bonic!", "right": "Que bonic!"}, {"wrong": "No sé que vol.", "right": "No sé què vol."}]}], "remember": ["Especificatives: *que* (no *el qual*); explicatives: *que* o *el qual* (no *qui*).", "Amb preposició: *què*, *qui*, *el qual*; mai *en la que* amb antecedent.", "*El dia que vaig nàixer*; *on* sense *a* en registre formal.", "Relatives neutres: *la qual cosa*, *cosa que*; *per a obtindre el qual*, *aprofitant la qual*.", "*N'hi ha que...*, *Hi ha qui...*", "Formal: *la xica a qui he demanat*, *l'amic el pare del qual*; *Què dimonis fas?*"], "sources": [{"gram": "GNV", "section": "24.2", "title": "Formes i usos dels relatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_2"}, {"gram": "GNV", "section": "24.3.1", "title": "Relatives explicatives amb antecedent repetit", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_3_1"}, {"gram": "GNV", "section": "24.3.2", "title": "Els relatius que, qui, què i article + qual", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_3_2"}, {"gram": "GNV", "section": "24.3.3", "title": "Els relatius adverbials", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_3_3"}, {"gram": "GNV", "section": "24.3.4", "title": "Les construccions de relatiu analítiques", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=24_3_4"}, {"gram": "GNV", "section": "23.2.2", "title": "Els pronoms no reflexius de tercera persona", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_2_2"}, {"gram": "GNV", "section": "25.2.3", "title": "Els interrogatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=25_2_3"}, {"gram": "GNV", "section": "19.3", "title": "Els pronoms indefinits", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=19_3"}, {"gram": "GVB", "section": "28.3.1", "title": "Que", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_3_1"}, {"gram": "GVB", "section": "28.3.2", "title": "Què", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_3_2"}, {"gram": "GVB", "section": "28.3.3", "title": "Qual", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_3_3"}, {"gram": "GVB", "section": "28.3.4", "title": "Qui", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=28_3_4"}, {"gram": "GVB", "section": "29.3", "title": "Què", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=29_3"}]}},
  {"type": "c2_mor_numerals", "lesson": {"intro": "Aprendràs a llegir i escriure fraccions, els numerals col·lectius (també els tradicionals com *grossa*, *tern* o *qüern*), els noms de períodes i efemèrides, els prefixos cults numerals i les interferències més freqüents en l'ús dels numerals.", "blocks": [{"title": "Lectura i escriptura de les fraccions", "text": "Els **partitius** tenen la mateixa forma que els **ordinals** (cultes o patrimonials en *-é*/*-ena*), excepte ***mig*** (*mitja*) i ***terç*** (*terça*). El numerador es llig amb el cardinal i el denominador amb el partitiu, que concorda en nombre. Sovint es reforcen amb el nom *part* (*una quarta part*, *la tercera part*), i per a ½ s'usa també ***la mitat*** (o *meitat*).", "table": {"head": ["fracció", "lectura"], "rows": [["1/2", "*un mig*; *la mitat* (o *meitat*)"], ["2/3", "*dos terços*"], ["3/4", "*tres quarts*"], ["2/5", "*dos cinquens* (o *quints*)"], ["8/10", "*huit desens* (o *dècims*)"], ["1/100", "*un centé* (o *centèsim*)"], ["1/1.000", "*un mil·lèsim*"]]}, "examples": ["**Dos terços** dels socis han votat a favor.", "Només en va rebre **la quarta part**.", "Han invertit **la mitat** dels ingressos."], "watch": [{"wrong": "un tercer dels vots", "right": "un terç dels vots (o la tercera part dels vots)"}]}, {"title": "Numerals col·lectius", "text": "Els col·lectius són **substantius** que expressen un conjunt d'un nombre concret d'entitats. La majoria tenen la forma de l'ordinal femení: *dotzena*, *quinzena*, *vintena*, *trentena*, *centena*. Uns altres tenen forma específica: *parell* (2), *tern* o *terna* (3), *qüern* (4), *quintern* (5), *centenar* (100), *miler* o *milenar* (1.000). Hi ha també col·lectius **tradicionals** de mesures i comptes: la ***grossa*** (dotze dotzenes) o el ***lustre*** (cinc anys).", "examples": ["Una **dotzena** d'ous i una **grossa** de botons.", "Un **centenar** de persones s'hi van concentrar.", "Vaig estar fora de casa una **quinzena**.", "Han passat ja dos **lustres** des de la inauguració."]}, {"title": "Períodes, efemèrides i edats", "text": "Alguns col·lectius cultes designen **períodes** de mesos (*bimestre*, *trimestre*, *quadrimestre*, *semestre*) i d'anys (*bienni*, *trienni*, *quadrienni*, *quinquenni*), **efemèrides** (*cinquantenari*, *centenari*, *mil·lenari*) i **franges d'edat** (*quinquagenari*, *octogenari*, *nonagenari*). Compte amb els adjectius de periodicitat: no és el mateix 'dos vegades' que 'cada dos'.", "table": {"head": ["adjectiu", "significat"], "rows": [["*bimensual*", "dos vegades al mes"], ["*bimestral*", "cada dos mesos"], ["*bianual*", "dos vegades a l'any"], ["*biennal*", "cada dos anys"], ["*quinzenal*", "cada quinze dies"], ["*semestral*", "cada sis mesos"]]}, "examples": ["El curs es dividix en dos **quadrimestres**.", "El càrrec té una durada d'un **quinquenni**.", "Celebrem el **centenari** de la societat musical.", "La biennal d'art se celebra **cada dos anys**."]}, {"title": "Prefixos cults numerals", "text": "Molts mots cultes es formen amb **formes prefixades** d'origen grec o llatí que indiquen un nombre: ***hemi-*** i ***semi-*** ('mig'), ***mono-*** i ***uni-*** ('un'), ***bi-*** / ***di-*** ('dos'), ***tri-*** ('tres'), ***quadri-*** / ***tetra-*** ('quatre'), ***penta-*** ('cinc'), ***hexa-*** ('sis'), ***multi-*** i ***poli-*** ('molts').", "table": {"head": ["prefix", "exemples"], "rows": [["*hemi-*", "*hemiplegia*, *hemicicle*, *hemisferi*"], ["*semi-*", "*semicercle*, *semiculte*, *semisec*"], ["*mono-* / *uni-*", "*monocràcia*, *monosíl·lab*; *unicolor*"], ["*bi-* / *tri-*", "*bicolor*, *bisíl·lab*; *trisíl·lab*, *trienni*"], ["*quadri-* / *tetra-*", "*quadrimestre*, *quadrienni*; *tetraedre*"], ["*penta-* / *hexa-*", "*pentàgon*; *hexàgon*, *hexaedre*"]]}}, {"title": "Interferències: u i un, ordinals i cardinals", "text": "El cardinal de la unitat és ***un*** quan modifica un substantiu (*un meló*, *dona-me'n un*), però ***u*** quan fa d'ordinal o designa el nom del número: *la pàgina u*, *el número u*, *l'u de gener*, *van dos a u*. Els ordinals *primer* i *segon* sempre varien en gènere i nombre (*la segona porta*). Amb noms de reis i papes, a partir de l'onze s'usen els **cardinals** (*Joan XXIII*: vint-i-tres), i darrere de *pàgina*, *capítol*, etc., també (*el capítol vint-i-u*).", "examples": ["És **el número u** de la classificació.", "La llei entra en vigor **l'u** de març.", "Llegiu **els capítols u i dos**.", "Han guanyat per **tres a u**."], "watch": [{"wrong": "el número un de la classificació", "right": "el número u de la classificació"}, {"wrong": "l'un de gener", "right": "l'u de gener"}, {"wrong": "la segon porta", "right": "la segona porta"}]}], "remember": ["Fraccions: *dos terços*, *tres quarts*, *dos cinquens*, *huit dècims*, *un centé*; *la mitat*.", "Col·lectius: *dotzena*, *quinzena*, *centenar*, *parell*, *tern*, *qüern*, *grossa* (144), *lustre* (5 anys).", "*Bimensual* (2 al mes) ≠ *bimestral* (cada 2 mesos); *bianual* ≠ *biennal*.", "*Quadrimestre*, *bienni*, *quinquenni*; *centenari*, *octogenari*.", "Prefixos: *hemi-*, *semi-*, *mono-*, *bi-*, *tri-*, *quadri-*, *tetra-*.", "*El número u*, *l'u de gener*, *la pàgina u*; però *un meló*."], "sources": [{"gram": "GNV", "section": "18.4.1", "title": "Caracterització general", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=18_4_1"}, {"gram": "GNV", "section": "18.4.2", "title": "Aspectes formals i sintàctics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=18_4_2"}, {"gram": "GNV", "section": "18.5", "title": "Els numerals partitius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=18_5"}, {"gram": "GNV", "section": "18.7", "title": "Els numerals col·lectius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=18_7"}, {"gram": "GNV", "section": "37.7", "title": "La prefixació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=37_7"}, {"gram": "GNV", "section": "38.2.2", "title": "La composició culta", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=38_2_2"}, {"gram": "GVB", "section": "22.2.3", "title": "Acotacions a l'ús de les formes un/u", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=22_2_3"}, {"gram": "GVB", "section": "22.3.2", "title": "Aspectes formals i sintàctics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=22_3_2"}, {"gram": "GVB", "section": "22.4", "title": "Els numerals partitius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=22_4"}, {"gram": "GVB", "section": "22.6", "title": "Els numerals col·lectius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=22_6"}]}},
  {"type": "c2_mor_indefinits", "lesson": {"intro": "Aprendràs les formes quantitatives tradicionals, les interferències més freqüents (*cap gràcia*, *alguna pressa*), els usos de *cada*, *altre* i *tal*, els valors de *tot*, la forma correcta de *qualsevol*, *ambdós*, *sengles* o *cert*, i els indefinits arcaics o molt formals.", "blocks": [{"title": "Formes tradicionals i interferències", "text": "El valencià conserva formes quantitatives tradicionals: ***manco*** (= *menys*), viva sobretot en *més o manco*, *ni menys ni manco* i *almanco*; o mesures com les ***onces*** de xocolate i els ***quinzets*** (antiga moneda: *Val dos quinzets*). Compte amb dos calcs: ***cap*** només va amb noms **comptables**; amb els incomptables s'usa ***gens de***. I per a 'una quantitat petita' d'un incomptable, cal ***una mica de***, *una miqueta de* o *un poc de*.", "examples": ["Hi havia, **més o manco**, dos-cents veïns.", "Berenava pa amb una **onça** de xocolate.", "Aquell acudit no té **gens de** gràcia.", "No et preocupes: no tinc **cap** pressa. / Tinc **una mica de** pressa."], "watch": [{"wrong": "No té cap gràcia.", "right": "No té gens de gràcia."}, {"wrong": "No ens queda cap arròs.", "right": "No ens queda gens d'arròs."}, {"wrong": "Tinc alguna pressa.", "right": "Tinc una mica (o una miqueta, o un poc) de pressa."}]}, {"title": "Cada, altre i tal", "text": "***Cada*** va sempre davant del nom i individualitza; en construccions partitives es diu *cada un* o *cadascun* (*cadascuna de les persones*). ***Altre*** s'usa amb article o amb un altre indefinit (*un altre*, *l'altre*, *qualsevol altra*), o sense res en plural (*altres persones*); amb el pronom *en* pren la preposició partitiva (*n'hi ha d'altres*). El pronom ***altri*** ('una altra persona') només viu en expressions fixes. ***Tal*** pot substituir un **nom propi** que no es vol dir: *En tal*, *tal i tal altre*.", "examples": ["He donat un caramel a **cada un** dels teus nebots.", "Este llibre ja l'he llegit; deixa-me'n **un altre**.", "Hi ha estes solucions, però **n'hi ha d'altres**.", "Respecta els béns **d'altri**.", "El testament començava així: «**En tal**, notari, fill de Gandia...».", "Escoltes **tal i tal altre**, i a mi no em fas cas."]}, {"title": "Els valors de tot", "text": "***Tot*** davant d'un determinant indica totalitat (*totes les teues amigues*); davant d'un nom sense determinant equival a 'qualsevol' (*Tota pedra fa paret*); amb *un* intensifica (*és tot un senyor*); amb numerals equival a l'article (*tots dos*). Davant d'un **topònim** pot concordar amb el seu gènere o quedar invariable. Davant d'un **adjectiu** o d'un adverbi no és indefinit sinó un quantitatiu de grau ('molt'), i concorda amb el nom.", "table": {"head": ["construcció", "exemple"], "rows": [["amb topònim", "*Viatjà per **tota** València.* / *Es recorregué **tot** Alcoi.*"], ["amb adjectiu ('molt')", "*Els xiquets tenien les mans **totes** brutes.* *Va arribar **tota** acalorada.*"], ["sense determinant ('qualsevol')", "***Tota** persona té drets fonamentals.*"], ["amb numeral", "***Tots dos** (o els dos) acudiren a la crida.*"], ["amb gerundi", "*Baixaven l'escala **tot** cridant.*"]]}}, {"title": "Qualsevol, ambdós, sengles, cert", "text": "Alguns indefinits demanen precisió formal. ***Qualsevol*** fa el plural ***qualssevol*** (amb doble *s* gràfica, sense diferència oral); les formes antigues ***qualsevulla*** i ***qualssevulla*** són arcaiques i molt formals. ***Ambdós*** ('els dos') pot fer el femení ***ambdues***. ***Sengles*** és invariable i **distributiu**: 'un per a cadascun'. ***Cert*** sense article vol dir 'algun, no especificat' (*fins a cert punt*); amb *un* significa 'una espècie de' (*un cert malestar*).", "examples": ["Les ajudes són compatibles amb **qualssevol** altres.", "Busca **unes flors qualssevulla** i dibuixa-les. (arcaic)", "**Ambdues** professores tenen la mateixa opinió.", "Els dos amics portaven **sengles** carpetes. (= una carpeta cadascun)", "Hi ha **un cert** malestar en l'ambient."], "watch": [{"wrong": "qualsevol altres solucions", "right": "qualssevol altres solucions"}, {"wrong": "Els dos portaven sengles carpeta.", "right": "Els dos portaven sengles carpetes."}]}, {"title": "Indefinits arcaics o molt formals", "text": "Alguns indefinits es perceben com a **arcaics** o **molt formals** i tenen equivalents més habituals. Convé reconéixer-los i usar-los només en registres literaris o molt formals.", "table": {"head": ["indefinit", "valor i equivalent", "exemple"], "rows": [["*mant*, *manta*, *mants*, *mantes*", "'molts, nombrosos'", "*El soroll es repetí **mantes** vegades.*"], ["*quelcom*", "'alguna cosa'", "*Hi ha **quelcom** que vullgues dir-me?*"], ["*altri*", "'una altra persona'", "*Ja no treballa per a **altri**.*"], ["*hom*", "subjecte impersonal: *es*, *la gent*", "***Hom** pensava que la Terra era plana.*"], ["*qualque*", "'algun'", "*Vindrà **qualque** dia.*"], ["*sengles*", "'un per a cadascun'", "*Portaven **sengles** carpetes.*"], ["*ambdós*", "'els dos', 'tots dos'", "***Ambdós** alumnes van traure la mateixa nota.*"]]}}], "remember": ["*Més o manco*, *ni menys ni manco*, *almanco*; *dos quinzets*, *una onça de xocolate*.", "*Cap* + comptable; *gens de* + incomptable: *gens de gràcia*, *gens d'arròs*.", "*Una mica de pressa*, no *alguna pressa*.", "*Cada un* / *cadascun*; *un altre*, *n'hi ha d'altres*; *en tal*, *tal i tal altre*.", "*Tota València*, *tot Alcoi*; *les mans totes brutes* ('molt').", "*Qualssevol*, *qualsevulla*, *ambdues*, *sengles*; arcaics: *mant*, *quelcom*, *altri*, *hom*, *qualque*."], "sources": [{"gram": "GNV", "section": "19.2.1", "title": "Els indefinits universals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=19_2_1"}, {"gram": "GNV", "section": "19.2.2", "title": "Els indefinits existencials", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=19_2_2"}, {"gram": "GNV", "section": "19.2.3", "title": "Els indefinits negatius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=19_2_3"}, {"gram": "GNV", "section": "19.3", "title": "Els pronoms indefinits", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=19_3"}, {"gram": "GNV", "section": "20.2", "title": "Aspectes formals i sintàctics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=20_2"}, {"gram": "GVB", "section": "24.2.2", "title": "Tot", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_2_2"}, {"gram": "GVB", "section": "24.2.3", "title": "Cada i cadascun", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_2_3"}, {"gram": "GVB", "section": "24.2.4", "title": "Sengles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_2_4"}, {"gram": "GVB", "section": "24.2.6", "title": "Qualsevol", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_2_6"}, {"gram": "GVB", "section": "24.2.9", "title": "Cert", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_2_9"}, {"gram": "GVB", "section": "24.2.13", "title": "Tal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_2_13"}, {"gram": "GVB", "section": "24.2.14", "title": "Cap", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_2_14"}, {"gram": "GVB", "section": "24.3.3", "title": "Altri i altre", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_3_3"}, {"gram": "GVB", "section": "24.3.5", "title": "Hom", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_3_5"}, {"gram": "GVB", "section": "24.3.7", "title": "Quelcom", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=24_3_7"}]}},
  {"type": "c2_mor_preposicions", "lesson": {"intro": "Aprendràs a usar amb precisió les preposicions simples i compostes (*cap* / *cap a*, *fins* / *fins a*, *com* / *com a*), a triar entre *per* i *per a* davant d'infinitiu, a respectar el règim dels verbs i la caiguda de la preposició davant de *que*, i a evitar els usos preposicionals no genuïns.", "blocks": [{"title": "Usos particulars de les preposicions simples", "text": "La preposició ***de*** introduïx la matèria, l'origen o una característica (*fa gust de peix*, *pantalons de ratlles*), i ***a*** pot introduir un infinitiu que complementa un pronom o un nom (*res a fer*). En els complements de **temps**, s'usa ***a*** amb sintagmes definits que indiquen un punt (una hora, una part del dia, un mes, una estació) i ***en*** amb sintagmes indefinits o duratius. Per a les parts del dia, en registres formals es preferix *a* a *per*.", "examples": ["Este caldo **fa gust de** peix.", "Duia uns pantalons **de** ratlles.", "Ja no hi ha **res a fer**.", "Arribarem **a** la vesprada; **a** l'agost descansarem.", "Ho acabarem **en** un moment."], "watch": [{"wrong": "Arribarem per la vesprada (registre formal).", "right": "Arribarem a la vesprada."}]}, {"title": "Preposicions compostes: cap a, fins a, com a", "text": "***Cap a*** es reduïx a ***cap*** davant dels adverbis *ací*, *allí*, *allà*, *amunt*, *avall*, *avant*, *arrere* i dels demostratius *aquest*, *aqueix*, *aquell*. ***Fins a*** es reduïx a ***fins*** davant d'adverbis díctics (*ara*, *demà*, *ahir*), de sintagmes preposicionals i d'oracions amb *que* o *fa*; en els usos no temporals ni espacials es manté *fins a* (*fins a sis persones*). ***Com a*** té valor predicatiu ('en qualitat de') o comparatiu, i es reduïx a ***com*** quan el terme porta determinant.", "table": {"head": ["forma reduïda", "forma composta"], "rows": [["*Anem **cap** allà.* *Mira **cap** amunt.*", "*Anem **cap a**l poble.* *Vindran **cap a** les quatre.*"], ["***Fins** demà.* ***Fins** que no t'ho pregunte.*", "***Fins a** la setmana que ve.* *Calien **fins a** sis persones.*"], ["*Plorava **com** un xiquet.*", "*Ploraven **com a** xiquets.* *T'ho dic **com a** amiga.*"]]}, "watch": [{"wrong": "Fins a demà!", "right": "Fins demà!"}, {"wrong": "Actuava com president.", "right": "Actuava com a president."}, {"wrong": "Obria uns ulls com a uns plats.", "right": "Obria uns ulls com uns plats (o com a plats)."}]}, {"title": "Per i per a davant d'infinitiu", "text": "Davant d'infinitiu, ***per*** introduïx la **causa** i la **mancança** (*estar per fer*), i també el final que expressa la intenció de **no** fer una cosa. Quan el subjecte és **agentiu** i l'infinitiu expressa la seua intenció, la llengua literària usa *per*, però també és acceptable *per a*. En canvi, s'usa ***per a*** quan falta la idea d'intencionalitat: subjecte inanimat, oració que no designa una acció o infinitiu que depén d'un nom, d'un adjectiu o d'un adverbi.", "table": {"head": ["valor", "exemple"], "rows": [["causa", "*Li van posar una multa **per** haver corregut massa.*"], ["mancança", "*Tots aquells pisos estan **per** vendre.*"], ["final negatiu", "*No menja **per** no embrutar.*"], ["final amb subjecte agentiu", "*Treballe **per** (o **per a**) guanyar-me la vida.*"], ["final sense intencionalitat", "*Esta caixa servirà **per a** guardar revistes.* *El termini **per a** matricular-se.*"]]}, "watch": [{"wrong": "Esta caixa servirà per guardar revistes.", "right": "Esta caixa servirà per a guardar revistes."}, {"wrong": "Menge per tindre fam.", "right": "Menge perquè tinc fam."}]}, {"title": "Règim verbal i caiguda de la preposició", "text": "Cal respectar la preposició que **regix** cada verb, encara que no coincidisca amb el castellà: *pensar **en***, *confiar **en***, *apel·lar* o *recórrer **contra** una sentència*; i en preguntes com *Què hi ha **per a** sopar* (o *de sopar*)? Davant de la conjunció ***que***, les preposicions àtones *a*, *en*, *de* i *amb* **cauen** en registres formals (*Confiava que guanyaria*). No cau, en canvi, quan forma part d'una conjunció, com la condicional ***amb que*** ('només que'). Davant d'infinitiu, alguns verbs canvien *en* o *amb* per *a* o *de* (*tardar a acabar*, *amenaçar de dir-ho*).", "examples": ["Sempre **pensa en** tu.", "Recorrerem **contra** la sentència.", "Què hi ha **per a** sopar?", "Confiava **que** guanyaria el premi. (no *en que*)", "N'hi ha prou **amb** dir-li-ho una volta. / **Amb que** li ho digues una volta, ja n'hi ha prou."], "watch": [{"wrong": "Confiava en que guanyaria.", "right": "Confiava que guanyaria."}, {"wrong": "S'alegra de que vingues.", "right": "S'alegra que vingues."}, {"wrong": "Tarden molt en acabar.", "right": "Tarden molt a acabar."}]}, {"title": "Usos preposicionals no genuïns", "text": "Algunes construccions són calcs o usos impropis. En les **dates** de les cartes i els documents, el lloc i la data es separen amb una coma, sense preposició. La locució de manera és ***a poc a poc***. L'obligació no s'expressa amb *hi ha que* ni *tindre que*, sinó amb *caldre* o *haver de*.", "table": {"head": ["no genuí", "genuí"], "rows": [["*Alacant, a 2 de febrer de 2026*", "*Alacant, 2 de febrer de 2026*"], ["*Menjava poc a poc.*", "*Menjava **a poc a poc**.*"], ["*Hi ha que fer-ho hui.*", "***Cal** fer-ho hui.*"], ["*Tinc que eixir.*", "***He d'**eixir.*"]]}}], "remember": ["*Fa gust de peix*, *pantalons de ratlles*, *res a fer*; *a la vesprada*, *en un moment*.", "*Cap allà*, *cap amunt* / *cap a casa*; *fins demà* / *fins a la setmana que ve*.", "*Com a president*, *com a xiquets*; però *com un xiquet*.", "*Per* (causa, mancança, intenció) / *per a* (finalitat sense intenció): *servix per a guardar*.", "*Pensar en*, *recórrer contra*; *confiava que* (sense *en*); *amb que li ho digues*.", "*Alacant, 2 de febrer*; *a poc a poc*; *cal*, *haver de*."], "sources": [{"gram": "GNV", "section": "26.3.1.2", "title": "Els complements de temps", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_1_2"}, {"gram": "GNV", "section": "26.3.4", "title": "Les preposicions per i per a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_4"}, {"gram": "GNV", "section": "26.3.5", "title": "L'elisió i el canvi de preposicions àtones", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_5"}, {"gram": "GNV", "section": "26.4.1", "title": "La preposició cap a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_4_1"}, {"gram": "GNV", "section": "26.4.2", "title": "Les preposicions des de i fins a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_4_2"}, {"gram": "GNV", "section": "26.4.3", "title": "La preposició com a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_4_3"}, {"gram": "GNV", "section": "32.4", "title": "El complement de règim", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_4"}, {"gram": "GNV", "section": "34.5.2", "title": "Les conjuncions condicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_2"}, {"gram": "GNV", "section": "31.3", "title": "Les perífrasis modals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=31_3"}, {"gram": "GVB", "section": "30.7", "title": "Per", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=30_7"}, {"gram": "GVB", "section": "30.8", "title": "Per a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=30_8"}, {"gram": "GVB", "section": "31.2", "title": "Cap a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=31_2"}, {"gram": "GVB", "section": "31.3", "title": "Com a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=31_3"}, {"gram": "GVB", "section": "31.8", "title": "Fins a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=31_8"}, {"gram": "GVB", "section": "19.2.6", "title": "L'ús de l'article definit davant dels anys", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_2_6"}]}},
  {"type": "c2_mor_preposicions_locucions", "lesson": {"intro": "Aprendràs l'ús genuí de les preposicions en frases fetes i locucions, les locucions prepositives correctes enfront de les interferències (*en base a*, *a nivell de*, *en quant a*...) i l'oposició entre *dalt*, *damunt* i *sobre*, d'una banda, i *baix*, *davall* i *sota*, de l'altra.", "blocks": [{"title": "Les preposicions en la fraseologia", "text": "Moltes frases fetes tenen una preposició **fixada** que no sempre coincidix amb la del castellà. Cal aprendre-les com a unitats.", "table": {"head": ["valencià", "castellà"], "rows": [["*posar **en** relleu*", "*poner de relieve*"], ["*estar **en** dejú*", "*estar en ayunas*"], ["***a** fosques*", "*a oscuras*"], ["*obrir **de** bat **a** bat*", "*abrir de par en par*"], ["*ple **de** gom **a** gom*", "*lleno a rebosar*"]]}, "examples": ["L'informe **posa en relleu** les mancances del servei.", "Per a l'anàlisi has d'anar **en dejú**.", "El teatre estava **de gom a gom**."], "watch": [{"wrong": "posar de relleu", "right": "posar en relleu"}]}, {"title": "Locucions prepositives genuïnes", "text": "La llengua disposa d'un ampli repertori de locucions amb valor de preposició: *a causa de*, *a força de* (o *a còpia de*), *a mitjan*, *arran de*, *en compte de*, *en lloc de*, *en virtut de*, *en vista de*, *per mitjà de*, *quant a*, *pel que fa a*, *en relació amb* (o *amb relació a*), *amb vista a*. També és admissible ***de cara a*** amb el valor de 'amb vista a', tot i que no convé abusar-ne.", "examples": ["**A força de** nadar ha adquirit tècnica.", "Les protestes han sorgit **arran de** les seues declaracions.", "**A mitjan** vesprada se'n va anar.", "**Quant a** l'horari, no hi haurà canvis.", "Han pactat **amb vista a** (o **de cara a**) les pròximes eleccions."]}, {"title": "Interferències i usos impropis", "text": "Algunes locucions prepositives són calcs que convé evitar, sobretot en els registres formals. ***A nivell de*** només és adequat en sentit **físic** ('a la mateixa altura que': *a nivell del mar*).", "table": {"head": ["evita", "usa"], "rows": [["*en base a*", "*d'acord amb*, *a partir de*"], ["*a nivell de* (sentit figurat)", "*en l'àmbit de*, *pel que fa a*"], ["*en quant a*", "*quant a*, *pel que fa a*"], ["*en relació a*", "*en relació amb*, *amb relació a*"]]}, "watch": [{"wrong": "En base a l'informe, s'ha decidit tancar.", "right": "D'acord amb l'informe, s'ha decidit tancar."}, {"wrong": "A nivell d'empresa, no hi ha problemes.", "right": "En l'àmbit de l'empresa (o Pel que fa a l'empresa), no hi ha problemes."}, {"wrong": "En relació a la consulta...", "right": "En relació amb la consulta..."}]}, {"title": "Dalt, damunt i sobre", "text": "En l'eix de la **superioritat**, el valencià distingix clarament ***damunt***, que implica normalment **contacte**, i ***dalt***, que significa 'en la part alta', sense contacte necessari. La preposició ***sobre*** també indica contacte, però el valencià la preferix per als valors **figurats** (el tema d'un discurs, 'a més de'). Davant de l'article, l'adverbi pot anar amb *de* o sense: *damunt de la taula* o *damunt la taula*.", "examples": ["T'he deixat la jaqueta **damunt de** la (o **sobre** la) cadira.", "Penja el quadre **dalt del** llit.", "Ens cridava **des de dalt de** l'escala.", "Parlarem **sobre** la redistribució de l'espai.", "**Sobre** (o **damunt de**) castigar-lo, encara li va pegar."]}, {"title": "Baix, davall i sota", "text": "En l'eix de la **inferioritat**, ***davall*** indica la part inferior, amb contacte o sense (*el llençol de davall*). ***Baix*** significa 'en la part baixa' i s'usa sovint sense complement; amb complement, té el valor de 'en una part més baixa', paral·lel a *dalt* (*des de baix de la serra*). **No** és acceptable *baix* + complement amb el valor de *davall* o *sota*. ***Sota*** és sinònim de *davall* i, a més, té usos figurats (*sota la seua tirania*, *sota zero*); la forma antiga *sots* es manté en el llenguatge jurídic (*sots pena*).", "examples": ["Pugeu pel camí que ix **des de baix de** la serra.", "El llençol **de damunt** i el **de davall**.", "No volen viure **davall** (o **sota**) la seua tirania.", "Estàvem a dos graus **sota** zero.", "Tira-li la carta per **davall de** la porta."], "watch": [{"wrong": "Viuen baix la seua tirania.", "right": "Viuen sota (o davall) la seua tirania."}, {"wrong": "Mira baix del llit.", "right": "Mira davall del llit."}]}], "remember": ["*Posar en relleu*, *en dejú*, *a fosques*, *de bat a bat*, *de gom a gom*.", "*A força de*, *arran de*, *a mitjan*, *quant a*, *en relació amb*, *amb vista a* (o *de cara a*).", "Evita *en base a*, *a nivell de* figurat, *en quant a*, *en relació a*.", "*Damunt* (contacte) / *dalt* (part alta) / *sobre* (preferit en sentit figurat).", "*Davall* (part inferior), *baix* (part baixa: *des de baix de la serra*), *sota* (també figurat).", "Mai *baix* + complement per *davall*/*sota*: *sota la seua tirania*."], "sources": [{"gram": "GNV", "section": "26.6", "title": "Les locucions preposicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_6"}, {"gram": "GNV", "section": "26.5.6", "title": "Les preposicions sobre i sota", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_5_6"}, {"gram": "GNV", "section": "27.4.2", "title": "Els adverbis preposicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=27_4_2"}, {"gram": "GVB", "section": "32.1", "title": "Les locucions preposicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=32_1"}, {"gram": "GVB", "section": "32.2", "title": "A base de", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=32_2"}, {"gram": "GVB", "section": "32.10", "title": "A força de", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=32_10"}, {"gram": "GVB", "section": "32.22", "title": "Amb vista a", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=32_22"}, {"gram": "GVB", "section": "32.30", "title": "En relació amb", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=32_30"}, {"gram": "GVB", "section": "31.16", "title": "Sobre", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=31_16"}, {"gram": "GVB", "section": "31.17", "title": "Sota", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=31_17"}, {"gram": "GVB", "section": "35.3.1", "title": "Damunt", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=35_3_1"}, {"gram": "GVB", "section": "35.3.2", "title": "Davall", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=35_3_2"}, {"gram": "GVB", "section": "35.3.3", "title": "Dalt", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=35_3_3"}, {"gram": "GVB", "section": "35.3.4", "title": "Baix", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=35_3_4"}, {"gram": "GVB", "section": "34.5.8", "title": "A fosques", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=34_5_8"}]}},
  {"type": "c2_mor_adverbis", "lesson": {"intro": "Aprendràs l'ús de la negació expletiva, el valor d'adverbis com *corrents*, *inclusivament*, *exclusivament* o *escaig*, els adverbis propis dels registres formals i la diferència entre parelles com *aleshores* / *a les hores*, *alhora* / *a l'hora*, *potser* / *pot ser* o *sobretot* / *sobre tot*.", "blocks": [{"title": "La negació expletiva", "text": "L'adverbi ***no*** pot aparéixer **sense valor negatiu** (negació expletiva) en tres contextos: les completives en subjuntiu que depenen de **verbs de temor**, les temporals amb *abans que* o *fins que* i les **comparatives** de superioritat. El seu ús és **opcional**. Compte: amb els verbs de temor pot crear ambigüitat (*Tenia por que no es casara*), i per això convé usar-lo només quan el context ho aclarix.", "examples": ["Temia que la seua decisió (**no**) haguera estat encertada.", "Este objecte té més valor que (**no**) el que se li atribuïx.", "Prepara el sopar abans que (**no**) vinga la mare.", "Treballa més en un dia que (**no**) tu en una setmana."]}, {"title": "Corrents, inclusivament, exclusivament, escaig", "text": "***Corrents*** és un adverbi que significa 'molt de pressa', i no s'ha de confondre amb el gerundi *corrent* ('caminant a gran velocitat'). ***Inclusivament*** indica que s'inclouen els límits esmentats, i ***exclusivament***, que no s'hi inclouen. ***Escaig*** designa la fracció que excedix una quantitat redona.", "examples": ["Li vaig demanar ajuda i me l'oferí **corrents**.", "He dinat **corrents** i ara em trobe malament.", "Hi ha festa fins al 2 de març **inclusivament**.", "El meu fill pesa trenta quilos **i escaig**."], "watch": [{"wrong": "Ho fa tot corrent i no n'encerta ni una (= de pressa).", "right": "Ho fa tot corrents i no n'encerta ni una."}]}, {"title": "Adverbis propis dels registres formals", "text": "Alguns adverbis i locucions són especialment adequats en els registres formals o literaris.", "table": {"head": ["adverbi", "valor", "exemple"], "rows": [["*enlloc*", "en cap lloc", "*No l'he trobat **enlloc**.*"], ["*força*", "molt (només en afirmatives; literari)", "*Té **força** llibres.*"], ["*dempeus* / *de peus*", "drets, sobre els peus", "*Ens ordenà que ens mantinguérem **dempeus**.*"], ["*a tothora*", "contínuament", "*Parla per telèfon **a tothora**.*"], ["*enjorn* / *d'hora*", "a les primeres hores, abans d'hora", "*Sempre s'alça **enjorn**.*"], ["*l'endemà* / *el sendemà*", "el dia següent", "*La llei entrarà en vigor **l'endemà** de la publicació.*"]]}, "watch": [{"wrong": "No té força ganes.", "right": "No té gaires ganes."}]}, {"title": "Locucions lexicalitzades: una paraula o dos", "text": "Algunes locucions adverbials s'han soldat en una sola paraula, amb un significat propi, que conviu amb el sintagma lliure de forma semblant. Cal distingir-los per l'escriptura i pel sentit.", "table": {"head": ["adverbi", "sintagma lliure"], "rows": [["*aleshores* ('llavors'): ***Aleshores** va entrar.*", "*a les hores*: *Obrim **a les hores** convingudes.*"], ["*alhora* ('al mateix temps'): *Reia i plorava **alhora**.*", "*a l'hora* ('puntualment'): *Diu que arribarà **a l'hora**.*"], ["*enlaire* ('a distància de terra'; 'pendent'): *La qüestió ha quedat **enlaire**.*", "*en l'aire*: *Hi havia molta pols **en l'aire**.*"], ["*potser* ('possiblement'): ***Potser** vindrà demà.*", "*pot ser* (verb): *Això no **pot ser**.* ***Pot ser** que ploga.*"], ["*sobretot* ('principalment'): *Sigues, **sobretot**, discret.*", "*sobre tot*: *Opina **sobre tot** el que passa.*"], ["*enlloc* ('en cap lloc'): *No el trobe **enlloc**.*", "*en lloc de* ('en substitució de'): ***En lloc d'**anar al cine, anirem al concert.*"]]}, "watch": [{"wrong": "Pot ser vindrà demà.", "right": "Potser vindrà demà."}, {"wrong": "Arribarem tots a l'hora (= al mateix temps).", "right": "Arribarem tots alhora."}]}], "remember": ["*No* expletiu (opcional): *Temia que no...*, *més valor que no...*, *abans que no vinga*.", "*Corrents* = molt de pressa; *inclusivament* / *exclusivament*; *trenta quilos i escaig*.", "Formals: *enlloc*, *força*, *dempeus*, *a tothora*, *enjorn*, *l'endemà* / *el sendemà*.", "*Aleshores* / *a les hores*; *alhora* / *a l'hora*.", "*Potser* / *pot ser*; *sobretot* / *sobre tot*.", "*Enlaire* / *en l'aire*; *enlloc* / *en lloc de*."], "sources": [{"gram": "GNV", "section": "27.7.2", "title": "Els adverbis d'afirmació i de negació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=27_7_2"}, {"gram": "GNV", "section": "27.5", "title": "Els adverbis de temps", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=27_5"}, {"gram": "GNV", "section": "28.5", "title": "Precisions sobre l'ús de l'indicatiu i el subjuntiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_5"}, {"gram": "GVB", "section": "38.2.3", "title": "Usos expletius de l'adverbi no", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=38_2_3"}, {"gram": "GVB", "section": "34.4.8", "title": "Corrents", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=34_4_8"}, {"gram": "GVB", "section": "34.4.10", "title": "Inclusivament", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=34_4_10"}, {"gram": "GVB", "section": "35.5.3", "title": "Enlloc", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=35_5_3"}, {"gram": "GVB", "section": "23.4.8", "title": "Força", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=23_4_8"}, {"gram": "GVB", "section": "36.2.7", "title": "Enjorn", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=36_2_7"}, {"gram": "GVB", "section": "36.2.13", "title": "Alhora", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=36_2_13"}, {"gram": "GVB", "section": "36.3.8", "title": "A tothora", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=36_3_8"}, {"gram": "GVB", "section": "38.1", "title": "Els adverbis modals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=38_1"}]}},
  {"type": "c2_mor_conjuncions", "lesson": {"intro": "Aprendràs a substituir els calcs en les conjuncions (*conforme*, *segons* progressiu), a distingir *mentre*, *mentre que*, *mentrestant* i *mentrimentres*, a col·locar *però* en diferents posicions, a reconéixer les conjuncions arcaiques (*jatsia*, *car*, *puix*) i a usar els connectors del discurs formal.", "blocks": [{"title": "Calcs i interferències", "text": "Algunes construccions són calcs que cal substituir. *Conforme* és un adjectiu ('d'acord', 'adequat'), no una conjunció de manera: cal ***tal com*** o ***com***. Per a expressar una progressió paral·lela s'usa ***a mesura que***, no *segons* (que sí que és correcte amb el valor de 'd'acord amb': *segons diu ell*). Amb valor consecutiu col·loquial s'usa ***doncs*** o ***per tant***, mai *pues*.", "table": {"head": ["calc", "forma genuïna"], "rows": [["*Situa els convidats conforme decidírem.*", "*Situa els convidats **tal com** decidírem.*"], ["*Segons s'acosta, m'emocione més.*", "***A mesura que** s'acosta, m'emocione més.*"], ["*Tens calor? Pues obri la finestra.*", "*Tens calor? **Doncs** obri la finestra.*"]]}}, {"title": "Mentre, mentre que, mentrestant, mentrimentres", "text": "***Mentre*** (o *mentres*) és una conjunció **temporal** de simultaneïtat. ***Mentre que*** té, d'acord amb l'ús més general, un valor **adversatiu** (contrast). ***Mentrestant*** és un **adverbi**: no introduïx cap oració, sinó que remet a una acció ja esmentada. ***Mentrimentres*** pot ser adverbi (= *mentrestant*) o conjunció (= *mentre*). La forma *mentre* és l'etimològica, preferida en registres formals, però *mentres* no és incorrecta.", "examples": ["**Mentre** tu prepares l'ensalada, jo pare taula.", "Joana treballa moltes hores, **mentre que** jo em limite a complir l'horari.", "Tu prepara l'ensalada; **mentrestant**, jo pararé taula.", "**Mentrimentres** ell parlava, tots callaven."], "watch": [{"wrong": "Mentrestant tu cuines, jo pare taula.", "right": "Mentre tu cuines, jo pare taula."}]}, {"title": "La col·locació de però", "text": "La conjunció adversativa ***però*** encapçala normalment el segon membre. Com que pot comportar-se com un adverbi connectiu, també pot anar **entre comes** dins de l'oració o al **final**, amb un valor semblant a *tanmateix*. No confongues ***sinó*** (valor substitutiu, després d'una negació) amb ***si no*** (condicional + negació).", "examples": ["Joan treballa molt, **però** no avança.", "Joan, **però**, no sabia res de tot això.", "Joan no sabia res de tot això, **però**.", "No m'ho ha dit ella **sinó** el seu germà.", "**Si no** vens, avisa'm."], "watch": [{"wrong": "No ho ha fet ell, si no la seua germana.", "right": "No ho ha fet ell, sinó la seua germana."}]}, {"title": "Conjuncions arcaiques i literàries", "text": "Algunes conjuncions es perceben avui com a **arcaiques** o pròpies de la **llengua literària**. Cal reconéixer-les i usar-les només en textos molt formals o d'estil elevat.", "table": {"head": ["conjunció", "valor", "equivalent actual"], "rows": [["*jatsia*", "concessiu (antic)", "*encara que*"], ["*car*", "causal (molt formal, literari)", "*perquè*, *ja que*"], ["*puix*, *puix que*", "causal", "*ja que*, *com que*"], ["*per tal com*", "causal (formal)", "*perquè*"], ["*per bé que*, *si bé*", "concessiu (formal)", "*encara que*"]]}, "examples": ["No hi aniré, **car** no m'hi han convidat.", "**Puix que** venen temps difícils, haurem de preparar-nos.", "**Jatsia** fora tard, continuà el viatge."]}, {"title": "Connectors del discurs formal", "text": "Els textos formals necessiten **connectors** variats i precisos. Els adverbis connectius estableixen relacions **textuals** i solen anar entre comes o després de punt i coma.", "table": {"head": ["relació", "connectors"], "rows": [["contrast", "*tanmateix*, *no obstant això*, *això no obstant*, *amb tot*, *així i tot*"], ["alternativa", "*altrament*"], ["conseqüència", "*per tant*, *per consegüent*, *consegüentment*, *així doncs*"], ["concessió", "*tot i que*, *malgrat que*, *per bé que*, *si bé*"], ["addició", "*a més*, *així mateix*"]]}, "examples": ["No ha estudiat gens; **tanmateix**, ha aprovat.", "Has de fer el treball; **altrament**, podries suspendre.", "Du una vida sana; **per consegüent**, té bona salut."]}], "remember": ["*Tal com decidírem* (no *conforme*); *a mesura que s'acosta* (no *segons*); *doncs* (no *pues*).", "*Mentre* (temps) / *mentre que* (contrast) / *mentrestant* (adverbi) / *mentrimentres*.", "*Però* a l'inici, entre comes o al final; *sinó* ≠ *si no*.", "Arcaiques o literàries: *jatsia*, *car*, *puix*, *per tal com*.", "Connectors: *tanmateix*, *no obstant això*, *amb tot*, *altrament*, *per consegüent*."], "sources": [{"gram": "GNV", "section": "34.3", "title": "Les conjuncions i altres classes de paraules", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_3"}, {"gram": "GNV", "section": "34.4.4", "title": "Les conjuncions adversatives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_4_4"}, {"gram": "GNV", "section": "34.5.3", "title": "Les conjuncions concessives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_3"}, {"gram": "GNV", "section": "34.5.4", "title": "Les conjuncions causals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_4"}, {"gram": "GNV", "section": "34.5.6", "title": "Les conjuncions consecutives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_6"}, {"gram": "GNV", "section": "34.5.7", "title": "Les conjuncions temporals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_7"}, {"gram": "GNV", "section": "34.5.8", "title": "Les conjuncions modals i comparatives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_8"}, {"gram": "GNV", "section": "27.8", "title": "Els adverbis textuals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=27_8"}, {"gram": "GVB", "section": "41.3.4", "title": "Les conjuncions adversatives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_3_4"}, {"gram": "GVB", "section": "41.4.4", "title": "Les conjuncions causals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_4"}, {"gram": "GVB", "section": "41.4.7", "title": "Les conjuncions temporals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_7"}, {"gram": "GVB", "section": "41.4.8", "title": "Les conjuncions modals i comparatives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_8"}]}},
  {"type": "c2_mor_concordanca_temporal", "lesson": {"intro": "Aprendràs a fer concordar els temps verbals en les oracions temporals, condicionals i completives, a usar l'indicatiu (i no el subjuntiu) amb els adverbis de dubte i a mantindre la coherència de les formes verbals al llarg d'un text.", "blocks": [{"title": "Temporals i relatives amb valor de futur", "text": "Quan una subordinada temporal (*quan*, *així que*, *tan bon punt*...) o una relativa sense antecedent es referix a una situació **posterior** al moment de parlar, el **futur** alterna amb el **present de subjuntiu**. El futur respon a l'ús més tradicional; el subjuntiu és avui el més habitual. En contextos de passat, l'alternança es dona entre el **condicional** i l'**imperfet de subjuntiu**.", "table": {"head": ["context", "exemple"], "rows": [["temporal de futur", "*Quan **anirem** / **anem** a escola, pararà de ploure.*"], ["relativa sense antecedent", "*Anirem on **voldrem** / **vullguem**.*"], ["posterioritat en el passat", "*Va dir que els qui **arribarien** / **arribaren** primer ho ordenarien tot.*"]]}, "watch": [{"wrong": "Quan arribe a casa, et cridaria.", "right": "Quan arribe (o arribaré) a casa, et cridaré."}]}, {"title": "Les condicionals", "text": "Les condicionals **reals** porten present d'indicatiu en la pròtasi i futur (o imperatiu) en l'apòdosi. Les **irreals** porten **imperfet de subjuntiu** en la pròtasi i **condicional** en l'apòdosi; col·loquialment també s'hi usa l'imperfet d'indicatiu (*Si no parlaves...*). Les irreals de **passat** porten plusquamperfet de subjuntiu i condicional perfet (que també pot adoptar les formes *haguera*, *hagueren*...). Darrere de la conjunció *si* no s'usen mai el futur ni el condicional.", "table": {"head": ["classe", "exemple"], "rows": [["real", "*Si ho **aprove** tot, me n'**aniré** d'acampada.*"], ["irreal", "*Si no **parlares** (o *parlaves*), **entendries** l'explicació.*"], ["irreal de passat", "*Si ho **haguera aprovat** tot, me n'**hauria** (o **haguera**) **anat**.*"]]}, "watch": [{"wrong": "Si plourà, no eixirem.", "right": "Si plou, no eixirem."}, {"wrong": "Si tindria temps, t'ajudaria.", "right": "Si tinguera temps, t'ajudaria."}]}, {"title": "Les completives i els verbs de temor", "text": "En les completives en subjuntiu, el temps depén del verb principal: amb un verb principal en present o futur s'usa el **present de subjuntiu**; amb un verb en passat o condicional, l'**imperfet de subjuntiu**. Amb els **verbs de temor**, l'indicatiu emfatitza la creença que passarà una cosa, i el subjuntiu, el desig que no passe: *Tem que li **pagarà** / **pague** més tard*.", "examples": ["Vol que demà **arribem** puntuals.", "Volia que **tornàrem** l'endemà.", "Tinc por que **pedregarà**. / Tinc por que **escriguen** la carta sense consultar-nos.", "M'agradaria que **pensara** igual que nosaltres."], "watch": [{"wrong": "Volia que tornem l'endemà.", "right": "Volia que tornàrem l'endemà."}, {"wrong": "M'agradaria que penses igual.", "right": "M'agradaria que pensares igual."}]}, {"title": "Adverbis de dubte amb indicatiu", "text": "Amb els adverbis de dubte ***potser***, ***possiblement*** i ***tal vegada***, el mode tradicional és l'**indicatiu**. L'ús del subjuntiu és una innovació no genuïna que cal evitar en els registres formals. Recorda, a més, que *a lo millor* és un calc: cal *potser*, *tal vegada* o *a la millor*.", "examples": ["**Potser** hui **és** el darrer dia de calor.", "**Possiblement** **arribaran** demà.", "**Tal vegada** **vindrà** en el tren de les deu.", "**Potser** **era** lleig, però tenia un atractiu especial."], "watch": [{"wrong": "Potser hui siga el darrer dia.", "right": "Potser hui és el darrer dia."}, {"wrong": "A lo millor ve demà.", "right": "Potser (o Tal vegada) vindrà demà."}]}, {"title": "Coherència de les formes verbals en el text", "text": "Un text ben construït manté un **eix temporal** coherent. Si la narració és en passat, el **futur del passat** s'expressa amb el **condicional** (*Va dir que vindria*), i l'anterioritat, amb el plusquamperfet (*havia arribat*). No barreges sense motiu el present i el passat, ni el passat perifràstic i el simple en el mateix fragment si no hi ha intenció estilística. En l'estil indirecte, els temps es traslladen d'acord amb el verb introductor.", "table": {"head": ["estil directe", "estil indirecte (passat)"], "rows": [["*«Vindré demà»*", "*Va dir que **vindria** l'endemà.*"], ["*«Ho he acabat»*", "*Va dir que ho **havia acabat**.*"], ["*«Quan arribe, t'avisaré»*", "*Va dir que quan **arribara** m'**avisaria**.*"]]}, "watch": [{"wrong": "Ens va prometre que vindrà l'endemà.", "right": "Ens va prometre que vindria l'endemà."}]}], "remember": ["*Quan anirem* / *quan anem*: futur tradicional, subjuntiu habitual.", "Real: *si aprove... aniré*; irreal: *si parlares... entendries*; mai *si plourà*, *si tindria*.", "Present → present de subjuntiu; passat → imperfet de subjuntiu: *Volia que tornàrem*.", "*Tem que li pagarà / pague*: indicatiu (creença) o subjuntiu (desig).", "*Potser hui és el darrer dia* (no *siga*).", "En passat: *Va dir que vindria*; coherència de temps en tot el text."], "sources": [{"gram": "GNV", "section": "28.2.1", "title": "El temps", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_2_1"}, {"gram": "GNV", "section": "28.3", "title": "El mode", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_3"}, {"gram": "GNV", "section": "28.4.1", "title": "Els temps verbals d'indicatiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_4_1"}, {"gram": "GNV", "section": "28.4.2", "title": "Els temps verbals de subjuntiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_4_2"}, {"gram": "GNV", "section": "28.5", "title": "Precisions sobre l'ús de l'indicatiu i el subjuntiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_5"}, {"gram": "GNV", "section": "29.5", "title": "Precisions sobre el polimorfisme verbal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_5"}, {"gram": "GNV", "section": "34.5.2", "title": "Les conjuncions condicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_2"}, {"gram": "GNV", "section": "34.5.7", "title": "Les conjuncions temporals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=34_5_7"}, {"gram": "GVB", "section": "39.2.2", "title": "El temps, l'aspecte i el mode", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=39_2_2"}, {"gram": "GVB", "section": "41.4.2", "title": "Les conjuncions condicionals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_2"}, {"gram": "GVB", "section": "41.4.7", "title": "Les conjuncions temporals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=41_4_7"}, {"gram": "GVB", "section": "19.5.2", "title": "Altres usos", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_5_2"}]}},
  {"type": "c2_mor_verbs_formes_no_personals", "lesson": {"intro": "Aprendràs el funcionament dels verbs defectius (*caldre*, *haver-hi* i els meteorològics), a evitar l'infinitiu de recapitulació i els gerundis incorrectes (consecutiu, copulatiu i especificatiu), i a construir correctament verbs coordinats amb règims diferents.", "blocks": [{"title": "Verbs defectius i impersonals", "text": "Alguns verbs no tenen tot el paradigma. ***Caldre*** ('ser necessari') només s'usa en tercera persona i substituïx els calcs *hi ha que* i *tindre que*. ***Haver-hi*** és impersonal: el sintagma que l'acompanya fa de complement directe, i en registres formals es preferix el verb en **singular** (*hi ha moltes cadires*), tot i que la concordança (*hi han*) també és acceptable. Els verbs **meteorològics** (*ploure*, *nevar*, *pedregar*, *plovisquejar*, *gotinyar*) són impersonals i s'usen en tercera persona del singular, llevat dels usos figurats (*Li plouen les ofertes*).", "examples": ["**Cal** que ens comuniqueu el resultat.", "No **cal** que vingues.", "**Hi havia** moltes persones a la plaça.", "Tota la vesprada ha estat **plovisquejant** (o **gotinyant**).", "Han dit que a la vesprada **pedregarà**."], "watch": [{"wrong": "Hi ha que estudiar més.", "right": "Cal estudiar més."}, {"wrong": "Tinc que eixir.", "right": "He d'eixir."}, {"wrong": "Hi havien moltes persones (registre formal).", "right": "Hi havia moltes persones."}]}, {"title": "L'infinitiu: recapitulació i ordes", "text": "S'ha estés l'ús, no recomanable, de l'**infinitiu com a verb principal** amb valor de recapitulació, sobretot en discursos orals. Cal usar un verb conjugat o una perífrasi. Tampoc s'ha d'usar l'infinitiu sol per a donar **ordes** o **prohibicions**: s'usa l'imperatiu o una forma impersonal.", "table": {"head": ["incorrecte", "correcte"], "rows": [["*Dir, com a conclusió, que estem satisfets.*", "***Cal dir** (o **hem de dir**), com a conclusió, que estem satisfets.*"], ["*Per a acabar, agrair-vos l'assistència.*", "*Per a acabar, **vos agraïm** l'assistència.*"], ["*Tancar la porta en eixir.*", "***Tanqueu** la porta en eixir.*"], ["*No fumar.*", "***Prohibit fumar.*** / ***Es prohibix** fumar.*"]]}}, {"title": "Gerundis incorrectes", "text": "El gerundi expressa **simultaneïtat** respecte a la principal. Per això és incorrecte amb valor de **posterioritat** o **conseqüència**, amb valor **copulatiu** (com si fora una oració coordinada) i amb valor **especificatiu**, com a modificador d'un nom en lloc d'una relativa. En tots estos casos cal una oració coordinada, una relativa o una construcció amb *per a*.", "table": {"head": ["ús incorrecte", "alternativa"], "rows": [["consecutiu: *No presentà el certificat, sent desqualificat.*", "*No presentà el certificat **i per això** (o **per la qual cosa**) **fon** desqualificat.*"], ["posterioritat: *Va caure trencant-se la cama.*", "*Va caure **i es va trencar** la cama.*"], ["copulatiu: *S'ha pagat la factura, servint este document com a justificant.*", "*S'ha pagat la factura, **i este document servix** com a justificant.*"], ["especificatiu: *Vos enviem una carta informant sobre les noves condicions.*", "*Vos enviem una carta **en què** (o **en la qual**) **vos informem** sobre les noves condicions.*"], ["especificatiu: *Han aprovat un decret regulant els estudis.*", "*Han aprovat un decret **que regula** els estudis.*"]]}}, {"title": "Usos correctes del gerundi", "text": "El gerundi és correcte quan expressa una acció **simultània** o la **manera**, i també quan té valor condicional o causal respecte a la principal. Amb *tot* davant, emfatitza la simultaneïtat. Amb alguns noms d'acció, percepció o comunicació pot anar com a complement amb valor de manera (*l'entrada del jugador vestint la roba de l'altre equip*).", "examples": ["Baixaven l'escala **tot cridant**.", "Va arribar **corrent** a l'estació.", "**Fent-ho** així, acabaràs abans.", "La foto mostra l'entrada del jugador **vestint** la roba de l'equip contrari."]}, {"title": "Verbs coordinats amb règims diferents", "text": "Quan es coordinen dos verbs que tenen un **règim diferent** (un és transitiu i l'altre porta preposició, o porten preposicions diferents), no poden compartir el mateix complement: cal que cada verb tinga el seu, i el segon sol aparéixer pronominalitzat. De la mateixa manera, en la llengua general no es coordinen preposicions davant d'un mateix complement, sinó sintagmes preposicionals complets.", "table": {"head": ["incorrecte", "correcte"], "rows": [["*Llig i parle d'un llibre.*", "*Llig **un llibre** i **en** parle.*"], ["*Entra i ix de casa contínuament.*", "*Entra **a casa** i **n'**ix contínuament.*"], ["*Conec i confie en la directora.*", "*Conec **la directora** i **hi** confie.*"], ["*Treballa per i per al poble.*", "*Treballa **pel poble** i **per al poble**.*"]]}}], "remember": ["*Cal*, *haver de* (no *hi ha que*, *tindre que*); formal: *hi havia moltes persones*.", "Meteorològics impersonals: *plou*, *neva*, *plovisqueja*, *gotinya*, *pedrega*.", "No *Dir, com a conclusió...*: *Cal dir...*, *Hem de dir...*; no infinitiu per a ordes.", "Gerundi només simultani o de manera; mai consecutiu, copulatiu ni especificatiu.", "*No presentà el certificat i per això fon desqualificat*; *una carta en què vos informem*.", "*Llig un llibre i en parle*; *pel poble i per al poble*."], "sources": [{"gram": "GNV", "section": "28.6.1", "title": "Caracterització general", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_6_1"}, {"gram": "GNV", "section": "28.6.2", "title": "Precisions sobre l'ús de les formes no personals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_6_2"}, {"gram": "GNV", "section": "31.3", "title": "Les perífrasis modals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=31_3"}, {"gram": "GNV", "section": "32.2", "title": "El complement directe i la transitivitat", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_2"}, {"gram": "GNV", "section": "8.5", "title": "L'oració", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=8_5"}, {"gram": "GNV", "section": "23.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_1"}, {"gram": "GNV", "section": "23.4.2", "title": "El pronom hi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_2"}, {"gram": "GNV", "section": "26.7", "title": "La seqüència de preposicions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_7"}, {"gram": "GVB", "section": "33.4", "title": "La correlació i coordinació de preposicions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=33_4"}, {"gram": "GVB", "section": "40.2.9", "title": "Haver de + infinitiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=40_2_9"}]}},
  {"type": "c2_mor_morfologia_verbal", "lesson": {"intro": "Aprendràs les formes verbals que es diferencien pel significat (*cuit* / *cogut*), per la varietat (*sigut* / *estat*), per ser arcaiques (*ésser*) o literàries (*patesca*), la variació dels incoatius, les formes formals del passat simple i de l'imperfet de subjuntiu, i els participis irregulars i dobles.", "blocks": [{"title": "Formes diferenciades", "text": "Alguns verbs tenen dos formes amb **significat** diferent: *coure* fa ***cuit*** quan vol dir 'preparar al foc' i ***cogut*** quan vol dir 'picar, fer coïssor'. Altres formes depenen de la **varietat** o del **registre**: el participi de *ser* és ***sigut*** en valencià i ***estat*** en altres parlars (tots dos acceptables); ***ésser*** és una variant antiga i formal de *ser*; *riure* fa *rist* o *rigut*, i *veure* alterna amb *vore*.", "table": {"head": ["parella", "diferència", "exemple"], "rows": [["*cuit* / *cogut*", "significat", "*He **cuit** l'arròs.* / *M'ha **cogut** la ferida.*"], ["*sigut* / *estat*", "varietat", "*Ha **sigut** (o **estat**) un èxit.*"], ["*ser* / *ésser*", "arcaisme, registre formal", "*Ha d'**ésser** aprovat pel ple.*"], ["*patisca* / *patesca*", "registre literari", "*No vull que **patisques** (lit. **patesques**).*"]]}}, {"title": "Els verbs incoatius", "text": "Els incoatius de la tercera conjugació afigen un **increment** en el present d'indicatiu i de subjuntiu i en l'imperatiu. En valencià general l'increment pren la vocal ***i*** (*servix*, *servixen*, *servisca*); en la llengua escrita també són vàlides les formes amb ***e*** en les persones 2, 3 i 6 del present d'indicatiu (*serveixes*, *serveix*, *serveixen*). Les formes amb *-esc-* (*servesc*, *servesca*, *patesca*) se senten **antigues i molt formals**. La pronunciació palatal (*servixc*) no es reflectix en l'escriptura.", "table": {"head": ["persona", "indicatiu", "subjuntiu"], "rows": [["1a", "*servisc*", "*servisca*"], ["2a", "*servixes* / *serveixes*", "*servisques*"], ["3a", "*servix* / *serveix*", "*servisca*"], ["6a", "*servixen* / *serveixen*", "*servisquen*"]]}, "watch": [{"wrong": "Que ho servixca.", "right": "Que ho servisca."}]}, {"title": "El passat simple", "text": "El **passat simple** (*cantí*, *cantares*, *cantà*, *cantàrem*, *cantàreu*, *cantaren*) és propi dels registres **formals** i **literaris**, i alterna amb el passat **perifràstic** (*vaig cantar*), que admet les variants *vas* o *vares*, *vam* o *vàrem*, *vau* o *vàreu*, *van* o *varen*. El passat simple de *ser* fa *fui*, *fores*, ***fon*** (o ***fou***), *fórem*, *fóreu*, *foren*.", "examples": ["L'any 1238 el rei **entrà** a València.", "No presentà el certificat i **fon** (o **fou**, o **va ser**) desqualificat.", "**Vam** (o **vàrem**) arribar tard."]}, {"title": "L'imperfet de subjuntiu i el condicional", "text": "L'imperfet de subjuntiu té en valencià general formes en ***-ra*** (*cantara*, *batera*, *sentira*), i en el valencià septentrional i en la tradició escrita, formes en ***-s***: *cantàs* o *cantés*, *batés*, *sentís*. Totes són acceptables. El **condicional perfet** pot adoptar les formes de *haver* en *-ria* o en *-ra*. Les terminacions antigues *-am*, *-au* del present de subjuntiu (*tingam*, *tingau*) no són pròpies del registre formal, que usa *-em*, *-eu*, *-im*, *-iu*.", "table": {"head": ["temps", "formes"], "rows": [["imperfet de subjuntiu", "*cantara* / *cantàs* / *cantés*; *batera* / *batés*; *sentira* / *sentís*"], ["plusquamperfet de subjuntiu", "*haguera cantat* / *hagués cantat*"], ["condicional perfet", "*hauria fet* / *haguera fet*"], ["present de subjuntiu (4a i 5a)", "*tinguem*, *tingueu* (no *tingam*, *tingau* en registre formal)"]]}}, {"title": "Participis irregulars i dobles", "text": "Molts verbs tenen participis **forts**. Els **sigmàtics** apareixen en els verbs en *-ndre* i *-metre* i en *imprimir* (***imprés***), *atényer* (*atés*), *empényer* (*empés*), *cloure* (*clos*); en *-t*, *dir* (*dit*), *dur* (*dut*), *traure* (*tret*) i els verbs en *-ldre* (***absolt***, *resolt*, *molt*), però *doldre* fa *dolgut*; en *-st*, *pondre* (*post*), *respondre* (*respost*), *veure* (*vist*). En valencià, *complir*, *oferir*, *establir*, *omplir* o *sofrir* fan participis regulars (***complit***, *oferit*, *establit*), mentre que *complert*, *ofert*... són propis d'altres parlars. Els derivats de *tindre* fan *-tingut*.", "examples": ["L'han **absolt** de tots els càrrecs.", "El llibre ja està **imprés**.", "Ha **complit** la seua paraula.", "La policia ha **detingut** el sospitós."], "watch": [{"wrong": "L'han detés.", "right": "L'han detingut."}, {"wrong": "Ha mantés la promesa.", "right": "Ha mantingut la promesa."}, {"wrong": "Ha absolgut l'acusat.", "right": "Ha absolt l'acusat."}]}], "remember": ["*He cuit l'arròs* / *m'ha cogut la ferida*; *sigut* o *estat*; *ésser* (formal).", "Incoatius: *servix* / *serveix*, *servisca*; *patesca*, *servesc*: literaris i antics.", "Passat simple formal: *cantà*, *fon* / *fou*; perifràstic *vam* o *vàrem cantar*.", "Imperfet de subjuntiu: *cantara* / *cantàs* / *cantés*; *hauria* o *haguera fet*.", "Participis: *imprés*, *absolt*, *resolt*, *dut*, *respost*; *complit*, *oferit* (en valencià).", "*Mantingut*, *detingut* (no *mantés*, *detés*)."], "sources": [{"gram": "GNV", "section": "29.3.2", "title": "Els verbs incoatius i els purs de la tercera conjugació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_3_2"}, {"gram": "GNV", "section": "29.5", "title": "Precisions sobre el polimorfisme verbal", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=29_5"}, {"gram": "GNV", "section": "30.2.4.3", "title": "Verbs amb passat simple i imperfet de subjuntiu forts", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_4_3"}, {"gram": "GNV", "section": "30.2.4.4", "title": "Els participis forts", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_2_4_4"}, {"gram": "GNV", "section": "28.4.1", "title": "Els temps verbals d'indicatiu", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=28_4_1"}, {"gram": "GNV", "section": "30.1", "title": "Conceptes generals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=30_1"}, {"gram": "GVB", "section": "39.3.1", "title": "Les tres conjugacions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=39_3_1"}, {"gram": "GVB", "section": "39.3.2", "title": "Els verbs regulars i els verbs irregulars", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=39_3_2"}]}},
  {"type": "c2_mor_verbs_pronominals", "lesson": {"intro": "Aprendràs les diferències de significat entre la forma pronominal i la no pronominal de verbs com *assentar*, *riure*, *semblar*, *oblidar*, *quedar* o *acordar*, els verbs que només són pronominals (*adonar-se*, *empassar-se*) i els que el castellà fa pronominals però el valencià no (o a l'inrevés).", "blocks": [{"title": "Canvi de significat amb el pronom", "text": "En molts verbs, la forma **pronominal** i la **no pronominal** tenen significats o construccions diferents. Cal triar-ne la forma adequada al sentit.", "table": {"head": ["forma no pronominal", "forma pronominal"], "rows": [["*assentar*: posar algú assegut o una cosa en posició estable (*assentar l'estàtua*)", "*assentar-se*: seure; establir-se una població"], ["*semblar*: paréixer; tindre semblança a algú (*li sembla a son pare*)", "*semblar-se*: tindre semblança entre ells (*se semblen molt*)"], ["*riure*: fer el gest d'alegria (també *riure's*)", "*riure's de*: burlar-se d'algú"], ["*oblidar* (tr.): *Ho he oblidat.*", "*oblidar-se de*: *M'he oblidat de la cita.*"], ["*quedar*: subsistir, resultar; concertar una cita (*Hem quedat a les cinc*)", "*quedar-se*: no moure's; apoderar-se d'una cosa (*s'ha quedat els diners*)"], ["*acordar*: decidir de comú acord (*Han acordat canviar l'ascensor*)", "*acordar-se*: posar-se d'acord (*S'acordaren per a anar d'excursió*)"]]}}, {"title": "Verbs només pronominals", "text": "Alguns verbs s'usen **sempre** amb pronom, i el pronom concorda amb el subjecte en totes les persones: ***adonar-se*** (de), ***empassar-se***, ***penedir-se*** (de), ***endur-se***, ***anar-se'n***. L'omissió del pronom és un error.", "examples": ["No **m'havia adonat** de la presència d'aquell home.", "**S'ha empassat** el pinyol sense voler.", "Diu que no **es penedix** de res.", "Quan va saber la notícia, **se'n va anar** sense dir res."], "watch": [{"wrong": "No havia adonat que plovia.", "right": "No m'havia adonat que plovia."}, {"wrong": "Has empassat la pastilla?", "right": "T'has empassat la pastilla?"}]}, {"title": "Calcs: pronominals en castellà, no en valencià", "text": "Alguns verbs són pronominals en castellà però **no** en valencià, o tenen un altre sentit. ***Caure*** no és pronominal: *M'ha caigut el got*. ***Acordar-se*** no significa 'recordar': per a la memòria s'usa ***recordar*** (transitiu) o ***recordar-se de***.", "table": {"head": ["calc", "forma genuïna"], "rows": [["*Se m'ha caigut el got.*", "*M'**ha caigut** el got.*"], ["*Se li han caigut les claus.*", "*Li **han caigut** les claus.*"], ["*No m'acorde del seu nom.*", "*No **recorde** el seu nom.* / *No **me'n recorde**.*"], ["*T'acordes de quan érem xicotets?*", "***Recordes** quan érem xicotets?* / ***Te'n recordes**?*"]]}}, {"title": "Verbs amb les dos construccions", "text": "Altres verbs admeten **les dos** construccions amb el mateix significat bàsic, i no s'han de corregir: *desdejunar* o *desdejunar-se*, *morir* o *morir-se*, *emmalaltir* o *emmalaltir-se*, *riure* o *riure's*. En alguns, la forma pronominal té, a més, un valor especial: *morir-se de ganes*, *desdejunar-se d'una notícia* ('tindre'n la primera notícia').", "examples": ["Sempre **desdejuna** (o **es desdejuna**) a les set.", "Les plantes **han mort** (o **s'han mort**) per la calor.", "Ens **moríem** de ganes que començara la festa.", "No sabia res: **me'n desdejune** ara mateix."]}, {"title": "Règim i pronominalització", "text": "Els verbs pronominals amb complement de règim (*adonar-se de*, *oblidar-se de*, *recordar-se de*, *penedir-se de*) perden la preposició **davant de *que*** en registres formals i el complement es pronominalitza amb ***en***. Recorda, a més, que amb *vosaltres* el pronom és *vos* (*vos n'adonareu*) i que en registres formals no es diu *se n'anirem* sinó ***ens n'anirem***.", "examples": ["No **es va adonar que** se n'havien anat. (no *de que*)", "**Me n'oblide** sempre, de les claus.", "**Vos en penedireu**, d'haver-ho dit.", "Demà **ens n'anirem** a primera hora."], "watch": [{"wrong": "No es va adonar de que plovia.", "right": "No es va adonar que plovia."}, {"wrong": "Se n'anirem demà.", "right": "Ens n'anirem demà."}]}], "remember": ["*Assentar* / *assentar-se* (seure); *semblar* / *semblar-se*; *riure* / *riure's de* (burlar-se).", "*Oblidar alguna cosa* / *oblidar-se d'alguna cosa*; *quedar* (cita) / *quedar-se* (romandre, apoderar-se).", "*Acordar* = decidir; *acordar-se* = posar-se d'acord (no 'recordar').", "Només pronominals: *adonar-se*, *empassar-se*, *penedir-se*, *endur-se*.", "*M'ha caigut el got* (no *se m'ha caigut*); *No me'n recorde*.", "*Desdejunar(-se)*, *morir(-se)*: les dos formes són correctes."], "sources": [{"gram": "GNV", "section": "23.2.1", "title": "Els pronoms reflexius i no reflexius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_2_1"}, {"gram": "GNV", "section": "32.2", "title": "El complement directe i la transitivitat", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_2"}, {"gram": "GNV", "section": "32.4", "title": "El complement de règim", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=32_4"}, {"gram": "GNV", "section": "23.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=23_4_1"}, {"gram": "GNV", "section": "26.3.5", "title": "L'elisió i el canvi de preposicions àtones", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=26_3_5"}, {"gram": "GVB", "section": "27.2.1", "title": "Els pronoms reflexius i no reflexius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_2_1"}, {"gram": "GVB", "section": "27.4.1", "title": "El pronom ne", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=27_4_1"}, {"gram": "GVB", "section": "26.4.2", "title": "La forma dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=26_4_2"}]}}
]$data$::jsonb) AS l(type text, lesson jsonb)
WHERE r.category = 'morfosintaxi' AND r.difficulty = 'C2' AND r.type = l.type;
